INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_MEANING', 'SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.BENEFITS_PRACTICE', 'skill', 'essential', 'Grade 5 Social Studies taught it first. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_COUNTRIES.M_PS_ADD_NEIGHBOUR', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_COUNTRIES', 'Adds Zambia, Malawi or the DR Congo to Eastern Africa because they are near Kenya''s neighbours.', '{"question":"Which country is in Eastern Africa?","wrong_answer":"Zambia","correct_answer":"Rwanda"}'::jsonb, 'The child counts every country that is close, not the countries of the region.', 'Offer "Zambia" next to the right answer and ask the question again in a new context.', 'List the ten countries of the region and ask the child to find the country in the list.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_COUNTRIES.M_PS_MISS_HORN', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_COUNTRIES', 'Leaves out Ethiopia, Somalia, Djibouti or Eritrea as if the region ended at Kenya''s borders.', '{"question":"Which list has only countries of Eastern Africa?","wrong_answer":"Kenya, Uganda, Tanzania, Rwanda","correct_answer":"Kenya, Ethiopia, Somalia, Tanzania"}'::jsonb, 'The child knows the East African Community partners best.', 'Offer "Kenya, Uganda, Tanzania, Rwanda" next to the right answer and ask the question again in a new context.', 'Ask for the countries on the Horn and ask whether they are east of Africa''s middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_COUNTRIES.M_PS_NORTH_AFRICA', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_COUNTRIES', 'Puts a North African or West African country (Egypt, Nigeria) in Eastern Africa.', '{"question":"Which one is NOT in Eastern Africa?","wrong_answer":"Burundi","correct_answer":"Egypt"}'::jsonb, 'The child places countries by their names, not the map.', 'Offer "Burundi" next to the right answer and ask the question again in a new context.', 'Use the compass: Egypt is on the Mediterranean in the north, far from the East coast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_POSITION_SIZE.M_PS_SIZE_NAME', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_POSITION_SIZE', 'Thinks Kenya is the largest country of Eastern Africa.', '{"question":"Which country is the largest in Eastern Africa?","wrong_answer":"Kenya","correct_answer":"Ethiopia"}'::jsonb, 'The child judges by the country he or she lives in.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Give the areas in square kilometres and ask the child to compare the numbers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_POSITION_SIZE.M_PS_LANDLOCKED', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_POSITION_SIZE', 'Says every Eastern African country has a sea coast, or that Uganda has a coast.', '{"question":"Which country has no sea coast?","wrong_answer":"Kenya","correct_answer":"Uganda"}'::jsonb, 'The child thinks a big lake is a coast.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Ask which ocean Uganda touches. Then trace where its ships must go to reach the sea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_POSITION_SIZE.M_PS_DIRECTION_SWAP', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_POSITION_SIZE', 'Puts Tanzania north of Kenya or Somalia west of Kenya.', '{"question":"In which direction does Tanzania lie from Kenya?","wrong_answer":"North","correct_answer":"South"}'::jsonb, 'The child mixes the compass points.', 'Offer "North" next to the right answer and ask the question again in a new context.', 'Stand on Nairobi on a map and say which way Mombasa to Dar es Salaam runs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_MEANING.M_LL_SWAP', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_MEANING', 'Swaps latitudes and longitudes: says latitudes run from north to south.', '{"question":"Which lines run from east to west on a map?","wrong_answer":"Longitudes","correct_answer":"Latitudes"}'::jsonb, 'The child links the word long with the lines that look long from top to bottom.', 'Offer "Longitudes" next to the right answer and ask the question again in a new context.', 'Draw the equator and say it is a latitude; ask which way it runs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_MEANING.M_LL_ZERO_LINES', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_MEANING', 'Says the equator is 0 degrees longitude or that the Prime Meridian is the equator.', '{"question":"Which line is 0 degrees latitude?","wrong_answer":"The Prime Meridian","correct_answer":"The equator"}'::jsonb, 'The child remembers that both lines are 0 and swaps their names.', 'Offer "The Prime Meridian" next to the right answer and ask the question again in a new context.', 'Ask: which line cuts the earth into north and south? Then give it its name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_MEANING.M_LL_MEASURES', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_MEANING', 'Thinks latitude measures how far east or west a place is.', '{"question":"What does the latitude of a place tell you?","wrong_answer":"How far east or west it is","correct_answer":"How far north or south of the equator it is"}'::jsonb, 'The child has not tied a measure to each set of lines.', 'Offer "How far east or west it is" next to the right answer and ask the question again in a new context.', 'Move a finger up and down a latitude line number: the number says north or south.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_LOCATE.M_LL_NORTH_SOUTH', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_LOCATE', 'Reads 1 degree S as north of the equator because Nairobi is in Kenya, where the equator crosses.', '{"question":"Nairobi is at about 1 degree S. Which side of the equator is it?","wrong_answer":"North of the equator","correct_answer":"South of the equator"}'::jsonb, 'The child ignores the letter after the number.', 'Offer "North of the equator" next to the right answer and ask the question again in a new context.', 'Ask: what does S stand for? Mark the equator on a sketch and put 1 S below it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_LOCATE.M_LL_EAST_WEST', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_LOCATE', 'Says every place in Eastern Africa is west of the Prime Meridian.', '{"question":"Kampala is at about 32 degrees E. Which side of the Prime Meridian is it?","wrong_answer":"West","correct_answer":"East"}'::jsonb, 'The child thinks Africa is west because it is far from Asia.', 'Offer "West" next to the right answer and ask the question again in a new context.', 'Read the E on the number and mark it on a sketch to the right of the 0 line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_LOCATE.M_LL_ORDER', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_LOCATE', 'Reads longitude before latitude when giving a position.', '{"question":"A place is written 4 N, 36 E. Which number is the latitude?","wrong_answer":"36","correct_answer":"4"}'::jsonb, 'The child reads the numbers in the order he or she likes.', 'Offer "36" next to the right answer and ask the question again in a new context.', 'Say the rule: latitude first (up and down), longitude second (across).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_COUNTRIES.M_PS_EAC_ONLY', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_COUNTRIES', 'Thinks Eastern Africa is only the East African Community members, so leaves out Ethiopia, Eritrea and Djibouti.', '{"question":"Is Ethiopia a country of Eastern Africa?","wrong_answer":"No, it is not in the EAC","correct_answer":"Yes, Ethiopia is in Eastern Africa"}'::jsonb, 'The child knows the EAC as "East Africa" and treats it as the whole region.', 'Offer "No, it is not in the EAC" next to the right answer and ask the question again in a new context.', 'Lay the EAC members on the map in one colour and the rest of Eastern Africa in another.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_POSITION_SIZE.M_PS_POPULATION_SIZE', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.PS_POSITION_SIZE', 'Judges the size of a country by how many people it has.', '{"question":"Rwanda has more people than Djibouti. Which is bigger in area?","wrong_answer":"Rwanda, it has more people","correct_answer":"Rwanda is bigger, but you must use the area, not the people"}'::jsonb, 'The child mixes up population and area, as in Grade 4.', 'Offer "Rwanda, it has more people" next to the right answer and ask the question again in a new context.', 'Compare the area column and the population column in a table.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_MEANING.M_LL_DEGREE_KM', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_MEANING', 'Thinks a degree of latitude is a distance in kilometres.', '{"question":"Nairobi is about 1 degree south. Does that mean it is 1 km from the equator?","wrong_answer":"Yes, 1 degree is 1 km","correct_answer":"No, a degree is a measure of angle on the globe, about 111 km of latitude"}'::jsonb, 'The child reads every number on a map as a distance.', 'Offer "Yes, 1 degree is 1 km" next to the right answer and ask the question again in a new context.', 'Show the degree marks round a globe and measure how far apart two lines are on the scale.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_LOCATE.M_LL_TOP_NORTH_ONLY', 'SOCI.G6.NATURA.POSITION_AND_SIZE_OF_COU.LL_LOCATE', 'Thinks places at the top of a map are always north of the equator, without reading the latitude.', '{"question":"Dodoma is near the top of a map of Tanzania. Its latitude is 6 degrees S. Is it north or south of the equator?","wrong_answer":"North, it is at the top of the map","correct_answer":"South"}'::jsonb, 'The child uses the map position, not the latitude.', 'Offer "North, it is at the top of the map" next to the right answer and ask the question again in a new context.', 'Draw the equator on the map first and look at which side Dodoma is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FEATURES.M_PF_KILI_COUNTRY', 'SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FEATURES', 'Puts Mount Kilimanjaro in Kenya because it is seen from Amboseli.', '{"question":"In which country is Mount Kilimanjaro?","wrong_answer":"Kenya","correct_answer":"Tanzania"}'::jsonb, 'The child has seen the mountain from the Kenyan side.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Find the peak on a map and say which side of the border its summit is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FEATURES.M_PF_TYPE_MIX', 'SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FEATURES', 'Calls a lake a river, or a mountain a lake, because of the name or the water.', '{"question":"What kind of feature is Lake Tanganyika?","wrong_answer":"A river","correct_answer":"A lake"}'::jsonb, 'The child trusts the picture and not the word in the name.', 'Offer "A river" next to the right answer and ask the question again in a new context.', 'Ask whether water has land all round it or runs in a line to the sea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FEATURES.M_PF_VICTORIA_COUNTRY', 'SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FEATURES', 'Thinks Lake Victoria belongs to Kenya only.', '{"question":"Which countries share Lake Victoria?","wrong_answer":"Kenya only","correct_answer":"Kenya, Uganda and Tanzania"}'::jsonb, 'The child sees the Kenyan shore at Kisumu.', 'Offer "Kenya only" next to the right answer and ask the question again in a new context.', 'Colour the three shores on a sketch in three colours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FORMATION.M_PF_ALL_VOLCANIC', 'SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FORMATION', 'Says all mountains in Eastern Africa are volcanic, including the Rwenzori.', '{"question":"How were the Rwenzori Mountains formed?","wrong_answer":"By volcanic eruptions","correct_answer":"By land being pushed up between faults"}'::jsonb, 'The child knows Kilimanjaro and Mount Kenya and assumes the rest.', 'Offer "By volcanic eruptions" next to the right answer and ask the question again in a new context.', 'Draw a block with two faults and push the middle up. Say block mountain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FORMATION.M_PF_RIFT_RIVER', 'SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FORMATION', 'Says a river carved the Great Rift Valley.', '{"question":"How was the Great Rift Valley formed?","wrong_answer":"A river cut it out over time","correct_answer":"The land between two faults dropped"}'::jsonb, 'The child sees valleys as made by rivers.', 'Offer "A river cut it out over time" next to the right answer and ask the question again in a new context.', 'Draw a long block that slides down between two cracks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FORMATION.M_PF_LAKE_VICTORIA_RIFT', 'SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FORMATION', 'Says Lake Victoria lies inside the Rift Valley like Lake Turkana.', '{"question":"Which lake lies in a shallow bowl made by the land sagging between the two arms of the Rift?","wrong_answer":"Lake Turkana","correct_answer":"Lake Victoria"}'::jsonb, 'The child puts every lake in the Rift.', 'Offer "Lake Turkana" next to the right answer and ask the question again in a new context.', 'Mark both arms of the Rift on a sketch and ask where Victoria sits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FEATURES.M_PF_NILE_SOURCE', 'SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FEATURES', 'Thinks the River Nile starts in Egypt and flows south into Lake Victoria.', '{"question":"Where does the White Nile flow from?","wrong_answer":"From Egypt into Lake Victoria","correct_answer":"Out of Lake Victoria at Jinja, northwards to Egypt"}'::jsonb, 'The child knows the Nile from Egypt and pictures it flowing into the lake.', 'Offer "From Egypt into Lake Victoria" next to the right answer and ask the question again in a new context.', 'Trace the Nile with a finger from Jinja northwards on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FORMATION.M_PF_VOLCANO_ACTIVE_ALL', 'SOCI.G6.NATURA.MAIN_PHYSICAL_FEATURES_I.PF_FORMATION', 'Thinks every volcanic mountain could erupt at any time.', '{"question":"Is Mount Kenya an active volcano that erupts today?","wrong_answer":"Yes, all volcanoes erupt","correct_answer":"No, it is an extinct volcano"}'::jsonb, 'The child links "volcanic" with eruptions seen on television.', 'Offer "Yes, all volcanoes erupt" next to the right answer and ask the question again in a new context.', 'Compare an extinct volcano (Mount Kenya) with an active one (Ol Doinyo Lengai, to confirm).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_REGIONS.M_CR_ARID_EQUATOR', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_REGIONS', 'Thinks places on the equator are always wet and hot, so puts northern Kenya in the equatorial region.', '{"question":"Which climate does northern Kenya have?","wrong_answer":"Equatorial","correct_answer":"Arid"}'::jsonb, 'The child says the equator crosses Kenya, so it is wet.', 'Offer "Equatorial" next to the right answer and ask the question again in a new context.', 'Compare a rain table of Kisumu and Lodwar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_REGIONS.M_CR_HIGHLAND_PLACE', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_REGIONS', 'Puts the highland region at the coast or beside the lakes.', '{"question":"Where is the highland climate found?","wrong_answer":"Along the coast","correct_answer":"On Mount Kenya and the Ethiopian Highlands"}'::jsonb, 'The child links climate to the sea and not to height.', 'Offer "Along the coast" next to the right answer and ask the question again in a new context.', 'Ask what happens to temperature as we climb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_TRAITS.M_CR_COOL_WET', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_TRAITS', 'Says the arid region is cool and wet, or the equatorial region is dry.', '{"question":"Which description fits the arid region?","wrong_answer":"Cool with plenty of rain","correct_answer":"Very hot with very little rain"}'::jsonb, 'The child swaps two descriptions.', 'Offer "Cool with plenty of rain" next to the right answer and ask the question again in a new context.', 'Use a two-line table: rain and heat for each region.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_TRAITS.M_CR_HEIGHT_HOT', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_TRAITS', 'Thinks high mountains near the equator are hotter than the plains.', '{"question":"Why is the top of Mount Kenya cold although it is on the equator?","wrong_answer":"It is nearer the sun so it is hot","correct_answer":"Air gets colder as height increases"}'::jsonb, 'The child thinks nearer the sun means hotter.', 'Offer "It is nearer the sun so it is hot" next to the right answer and ask the question again in a new context.', 'Use the fact that temperature falls with height; ask about the snow on Kilimanjaro.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_INFLUENCE.M_CR_FARM_ALL', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_INFLUENCE', 'Says the same crops can be grown anywhere whatever the climate.', '{"question":"Why is tea grown in the cool, wet highlands?","wrong_answer":"It can be grown anywhere","correct_answer":"It needs cool weather and plenty of rain"}'::jsonb, 'The child does not link crops to climate.', 'Offer "It can be grown anywhere" next to the right answer and ask the question again in a new context.', 'Ask what happens to tea in the dry north.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_INFLUENCE.M_CR_DROUGHT_FLOOD', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_INFLUENCE', 'Says drought causes floods, or heavy rain causes hunger by drought.', '{"question":"What does a long drought cause?","wrong_answer":"Floods","correct_answer":"Crop failure and hunger"}'::jsonb, 'The child confuses too little and too much rain.', 'Offer "Floods" next to the right answer and ask the question again in a new context.', 'Draw rain cloud and no rain cloud and say what each does to farms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_REGIONS.M_CR_ONE_COUNTRY_ONE', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_REGIONS', 'Thinks each country has only one climate.', '{"question":"Does Kenya have one climatic region or several?","wrong_answer":"One, the Kenyan climate","correct_answer":"Several: arid, semi-arid, tropical, highland and coastal"}'::jsonb, 'The child names a climate after a country.', 'Offer "One, the Kenyan climate" next to the right answer and ask the question again in a new context.', 'Colour the climate map: Kenya has many colours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_REGIONS.M_CR_MOUNTAIN_REGION_LOW', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_REGIONS', 'Places the mountain climate on low plains because mountains are large.', '{"question":"Where is the mountain climate found?","wrong_answer":"On the low plains","correct_answer":"On high mountains such as Kilimanjaro and Mount Kenya"}'::jsonb, 'The child links the region''s name to size rather than height.', 'Offer "On the low plains" next to the right answer and ask the question again in a new context.', 'Shade the mountains on the relief map and the mountain climate on the climate map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_TRAITS.M_CR_TROPICAL_WET_ALL', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_TRAITS', 'Thinks the tropical region is wet all year like the equatorial region.', '{"question":"How many main seasons does the tropical (savanna) region have?","wrong_answer":"One, wet all year","correct_answer":"Two: a wet season and a dry season"}'::jsonb, 'Both regions are near the equator.', 'Offer "One, wet all year" next to the right answer and ask the question again in a new context.', 'Compare a Kampala and a Dodoma rainfall graph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_TRAITS.M_CR_ARID_COLD', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_TRAITS', 'Thinks deserts are always hot, so the arid region has no cool nights.', '{"question":"What are nights like in the arid region?","wrong_answer":"Hot like the day","correct_answer":"Often cool, because there are few clouds"}'::jsonb, 'The child thinks only of hot days.', 'Offer "Hot like the day" next to the right answer and ask the question again in a new context.', 'Read day and night temperatures for Lodwar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_INFLUENCE.M_CR_TEA_DRY', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_INFLUENCE', 'Thinks tea grows best in hot, dry lowlands.', '{"question":"Where does tea grow best?","wrong_answer":"In hot, dry lowlands","correct_answer":"In cool, wet highlands"}'::jsonb, 'The child links tea to heat because it is drunk hot.', 'Offer "In hot, dry lowlands" next to the right answer and ask the question again in a new context.', 'Show Kericho on the climate map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_INFLUENCE.M_CR_NOMAD_LAZY', 'SOCI.G6.NATURA.CLIMATIC_REGIONS_IN_EAST.CR_INFLUENCE', 'Thinks herders move because they do not want to farm.', '{"question":"Why do herders in the arid north move with their animals?","wrong_answer":"They do not want to settle","correct_answer":"To find water and pasture when the land dries"}'::jsonb, 'The child judges a way of life by their own.', 'Offer "They do not want to settle" next to the right answer and ask the question again in a new context.', 'Show a dry-season map of water points.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TYPES.M_VG_SAVANNA_WHERE', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TYPES', 'Puts savanna in the cold mountain tops or the coast.', '{"question":"Where is savanna grassland found?","wrong_answer":"The Serengeti and the Maasai Mara","correct_answer":"The top of Mount Kenya"}'::jsonb, 'The child ties grassland to nothing.', 'Offer "The Serengeti and the Maasai Mara" next to the right answer and ask the question again in a new context.', 'Connect grassland and wildlife: ask where zebra and wildebeest live.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TYPES.M_VG_MANGROVE_PLACE', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TYPES', 'Says mangroves grow in the desert or in cold mountains.', '{"question":"Where do mangrove forests grow?","wrong_answer":"In the desert","correct_answer":"On the salty coast"}'::jsonb, 'The child has no picture of a mangrove.', 'Offer "In the desert" next to the right answer and ask the question again in a new context.', 'Show a picture of stilt roots in the sea water at the coast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TYPES.M_VG_RAINFOREST_DRY', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TYPES', 'Puts tropical rain forest in the dry north.', '{"question":"Which climate suits rain forest?","wrong_answer":"Dry and hot","correct_answer":"Hot and wet all year"}'::jsonb, 'The child does not link vegetation to rain.', 'Offer "Dry and hot" next to the right answer and ask the question again in a new context.', 'Ask which plants need the most water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TRAITS.M_VG_DESERT_BROAD', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TRAITS', 'Says desert plants have broad leaves and shallow roots.', '{"question":"Which description fits desert plants?","wrong_answer":"Broad leaves and shallow roots","correct_answer":"Thorns, small leaves and long roots"}'::jsonb, 'The child draws all plants like garden plants.', 'Offer "Broad leaves and shallow roots" next to the right answer and ask the question again in a new context.', 'Ask how a plant would keep water in a hot, dry place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TRAITS.M_VG_SAVANNA_TREES', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TRAITS', 'Says savanna is thick forest with tall trees close together.', '{"question":"Which description fits savanna?","wrong_answer":"Thick forest with tall trees close together","correct_answer":"Tall grass with scattered flat-topped trees"}'::jsonb, 'The child mixes savanna and rain forest.', 'Offer "Thick forest with tall trees close together" next to the right answer and ask the question again in a new context.', 'Draw the Mara plain with a few acacia trees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TRAITS.M_VG_MOUNTAIN_SAME', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TRAITS', 'Thinks the vegetation is the same from the bottom to the top of a mountain.', '{"question":"How does vegetation change as you climb Mount Kenya?","wrong_answer":"It stays the same","correct_answer":"It changes from forest to bamboo to moorland to bare rock"}'::jsonb, 'The child pictures one kind of plant per mountain.', 'Offer "It stays the same" next to the right answer and ask the question again in a new context.', 'Draw the mountain in four bands.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_CONSERVE.M_VG_BURN_OK', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_CONSERVE', 'Thinks burning bush helps vegetation grow back and is a good way of conserving it.', '{"question":"Which action conserves vegetation?","wrong_answer":"Burning the bush to clear it","correct_answer":"Planting trees where they were cut"}'::jsonb, 'The child sees new grass after a fire and thinks fire helps.', 'Offer "Burning the bush to clear it" next to the right answer and ask the question again in a new context.', 'Ask what burning does to soil, animals and young trees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_CONSERVE.M_VG_CUT_FOR_MONEY', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_CONSERVE', 'Thinks cutting forests for charcoal helps people so it does not harm vegetation.', '{"question":"What happens when a forest is cut for charcoal?","wrong_answer":"More rain falls","correct_answer":"The soil is exposed and may be washed away"}'::jsonb, 'The child sees only the money gained.', 'Offer "More rain falls" next to the right answer and ask the question again in a new context.', 'Ask what holds the soil when the trees are gone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TYPES.M_VG_FOREST_EVERYWHERE', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TYPES', 'Thinks most of Eastern Africa is covered in thick forest.', '{"question":"Which vegetation covers most of Eastern Africa?","wrong_answer":"Thick rain forest","correct_answer":"Savanna grassland"}'::jsonb, 'The child pictures Africa as a jungle from films.', 'Offer "Thick rain forest" next to the right answer and ask the question again in a new context.', 'Shade the vegetation map: most of it is savanna.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TRAITS.M_VG_THORNS_WHY', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_TRAITS', 'Thinks desert plants have thorns only to hurt animals.', '{"question":"Why do many desert plants have thorns instead of broad leaves?","wrong_answer":"Only to hurt animals","correct_answer":"To lose less water and to protect them from being eaten"}'::jsonb, 'The child sees only the defence.', 'Offer "Only to hurt animals" next to the right answer and ask the question again in a new context.', 'Put a broad leaf and a thorny twig in the sun and compare after an hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_CONSERVE.M_VG_ONE_TREE_ENOUGH', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_CONSERVE', 'Thinks planting one tree for every forest cut down makes up for it.', '{"question":"A company cuts 100 trees and plants one. Has it conserved the forest?","wrong_answer":"Yes, it planted a tree","correct_answer":"No, it must replant many more and let them grow"}'::jsonb, 'The child counts the action, not the amount.', 'Offer "Yes, it planted a tree" next to the right answer and ask the question again in a new context.', 'Count trees cut and planted on the board.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_CONSERVE.M_VG_GOVT_ONLY_CONSERVE', 'SOCI.G6.NATURA.VEGETATION_IN_EASTERN_AF.VG_CONSERVE', 'Thinks only the Kenya Forest Service can conserve vegetation.', '{"question":"What can a school do to conserve vegetation?","wrong_answer":"Nothing, it is the government''s job","correct_answer":"Plant trees, keep a tree nursery and use energy-saving jikos"}'::jsonb, 'The child hears of forest guards and thinks it is their work alone.', 'Offer "Nothing, it is the government''s job" next to the right answer and ask the question again in a new context.', 'Start or visit the school tree nursery.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_SITES.M_HB_BUILT_NATURAL', 'SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_SITES', 'Calls a natural feature such as Mount Kenya a historic built environment.', '{"question":"Which one is a historic built environment?","wrong_answer":"Mount Kenya","correct_answer":"Fort Jesus"}'::jsonb, 'The child links any old place to history.', 'Offer "Mount Kenya" next to the right answer and ask the question again in a new context.', 'Ask: did people build it or was it made by nature?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_SITES.M_HB_COUNTRY', 'SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_SITES', 'Puts Lalibela in Kenya or Stone Town in Uganda.', '{"question":"In which country are the rock-hewn churches of Lalibela?","wrong_answer":"Kenya","correct_answer":"Ethiopia"}'::jsonb, 'The child places sites by region and not by country.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Match sites and countries on a small table and say each aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_SITES.M_HB_FORT_JESUS', 'SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_SITES', 'Says Fort Jesus was built by the British or the Arabs in modern times.', '{"question":"Who built Fort Jesus in Mombasa?","wrong_answer":"The British","correct_answer":"The Portuguese"}'::jsonb, 'The child links every old building with colonial rule.', 'Offer "The British" next to the right answer and ask the question again in a new context.', 'Ask about the date: 1593 is before the British came.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_VALUE.M_HB_NO_VALUE', 'SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_VALUE', 'Thinks old buildings should be pulled down because they are useless.', '{"question":"Why do we conserve old buildings and museums?","wrong_answer":"They are useless and should be pulled down","correct_answer":"They teach us our history and bring tourists"}'::jsonb, 'The child values only new things.', 'Offer "They are useless and should be pulled down" next to the right answer and ask the question again in a new context.', 'Ask what a visitor learns at Lamu Old Town.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_VALUE.M_HB_TOUCH_ALL', 'SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_VALUE', 'Thinks writing names on or taking stones from a site shows love for it.', '{"question":"Which action conserves a historic site?","wrong_answer":"Writing your name on the old wall","correct_answer":"Following the rules and listening to the guide"}'::jsonb, 'The child wants to leave a mark.', 'Offer "Writing your name on the old wall" next to the right answer and ask the question again in a new context.', 'Ask what happens to a wall when a thousand visitors write on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_SITES.M_HB_KASUBI_KENYA', 'SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_SITES', 'Puts the Kasubi Tombs in Kenya.', '{"question":"In which country are the Kasubi Tombs?","wrong_answer":"Kenya","correct_answer":"Uganda"}'::jsonb, 'The child places every famous site in Kenya first.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Put a pin for each site on the regional map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_VALUE.M_HB_TOURISM_ONLY_VALUE', 'SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_VALUE', 'Thinks historic sites matter only for tourist money.', '{"question":"Give a reason a historic site matters besides tourism.","wrong_answer":"There is no other reason","correct_answer":"It teaches our history and gives us identity"}'::jsonb, 'Income is the reason heard most.', 'Offer "There is no other reason" next to the right answer and ask the question again in a new context.', 'Ask what a learner learns on a visit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_VALUE.M_HB_MODERN_REBUILD', 'SOCI.G6.NATURA.HISTORIC_BUILT_ENVIRONME.HB_VALUE', 'Thinks rebuilding an old site with new concrete conserves it.', '{"question":"An old coral wall is cracking. Which is the better repair?","wrong_answer":"Pull it down and build a concrete one","correct_answer":"Repair it carefully with the same kind of materials"}'::jsonb, 'The child thinks newer means stronger and better.', 'Offer "Pull it down and build a concrete one" next to the right answer and ask the question again in a new context.', 'Compare a photo of a careful coral repair with a concrete wall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_CLASSIFY.M_LG_GROUP_SWAP', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_CLASSIFY', 'Puts the Maasai or Luo in the Bantu group because they live near Bantu communities.', '{"question":"Which language group do the Luo belong to?","wrong_answer":"Bantu","correct_answer":"Nilotic"}'::jsonb, 'The child sorts by where people live, not by language.', 'Offer "Bantu" next to the right answer and ask the question again in a new context.', 'Say the language families: Bantu, Nilotic, Cushitic, and name two for each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_CLASSIFY.M_LG_SOMALI', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_CLASSIFY', 'Puts the Somali in the Nilotic or Bantu group.', '{"question":"Which language group do the Somali belong to?","wrong_answer":"Nilotic","correct_answer":"Cushitic"}'::jsonb, 'The child does not know the Cushitic group.', 'Offer "Nilotic" next to the right answer and ask the question again in a new context.', 'Link Cushitic with the Horn: Somali, Oromo, Afar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_CLASSIFY.M_LG_SUBGROUP', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_CLASSIFY', 'Puts the Maasai among the Highland Nilotes and the Kalenjin among the Plain Nilotes.', '{"question":"Which sub-group of the Nilotes do the Maasai belong to?","wrong_answer":"Highland Nilotes","correct_answer":"Plain Nilotes"}'::jsonb, 'The child swaps two sub-groups that are both Nilotic.', 'Offer "Highland Nilotes" next to the right answer and ask the question again in a new context.', 'Say Plain Nilotes live on the plains and herd cattle, like the Maasai and the Turkana.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_REASONS_ROUTES.M_LG_NO_REASON', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_REASONS_ROUTES', 'Says people migrated only because they wanted to travel for fun.', '{"question":"Why did many groups move to new lands?","wrong_answer":"To travel for fun","correct_answer":"To look for pasture, water and fertile land"}'::jsonb, 'The child has not thought about need.', 'Offer "To travel for fun" next to the right answer and ask the question again in a new context.', 'Ask what a herder does when the grass is gone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_REASONS_ROUTES.M_LG_BANTU_ORIGIN', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_REASONS_ROUTES', 'Says the Bantu came from Ethiopia or South Sudan.', '{"question":"Where did the Bantu come from?","wrong_answer":"Ethiopia","correct_answer":"The Congo Basin"}'::jsonb, 'The child mixes the origins of the three groups.', 'Offer "Ethiopia" next to the right answer and ask the question again in a new context.', 'Match each group with its homeland in a three-row table.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_REASONS_ROUTES.M_LG_CUSH_DIRECTION', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_REASONS_ROUTES', 'Says the Cushites moved north from Kenya into Ethiopia.', '{"question":"Which way did the Cushites move into Kenya?","wrong_answer":"North","correct_answer":"South"}'::jsonb, 'The child reverses the direction of movement.', 'Offer "North" next to the right answer and ask the question again in a new context.', 'Find Ethiopia and Kenya on a map and say which is north.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_EFFECTS.M_LG_NO_CONFLICT', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_EFFECTS', 'Says migration and settlement never caused quarrels.', '{"question":"What problem could settlement cause?","wrong_answer":"No problems at all","correct_answer":"Quarrels over land and pasture"}'::jsonb, 'The child sees only the good effects.', 'Offer "No problems at all" next to the right answer and ask the question again in a new context.', 'Ask what happens when two herds need the same water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_EFFECTS.M_LG_ALL_SAME', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_EFFECTS', 'Says after settlement all communities became the same.', '{"question":"What happened when groups settled near each other?","wrong_answer":"They all became the same","correct_answer":"They traded and some intermarried"}'::jsonb, 'The child over-generalises mixing.', 'Offer "They all became the same" next to the right answer and ask the question again in a new context.', 'Ask whether Kikuyu and Maasai speak the same language today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_CLASSIFY.M_LG_COUNTRY_GROUP', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_CLASSIFY', 'Thinks each country has only one language group.', '{"question":"Are all Ugandans in the same language group?","wrong_answer":"Yes, one country one group","correct_answer":"No: the Baganda are Bantu and the Acholi are Nilotes"}'::jsonb, 'The child links a language group to a flag.', 'Offer "Yes, one country one group" next to the right answer and ask the question again in a new context.', 'Sort communities from one country into all three groups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_REASONS_ROUTES.M_LG_ONE_MOVE', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_REASONS_ROUTES', 'Thinks each group moved once, in one trip, to where it lives now.', '{"question":"Did the Bantu reach Eastern Africa in one journey?","wrong_answer":"Yes, in one trip","correct_answer":"No, they moved slowly over hundreds of years"}'::jsonb, 'Arrows on a map look like one journey.', 'Offer "Yes, in one trip" next to the right answer and ask the question again in a new context.', 'Draw the arrow in short steps with dates beside them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_EFFECTS.M_LG_EFFECT_ONLY_BAD', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_EFFECTS', 'Thinks migration only caused wars.', '{"question":"Give one good effect of migration.","wrong_answer":"There were none","correct_answer":"Intermarriage, trade, and the spread of farming and iron working"}'::jsonb, 'Conflict stories are remembered most.', 'Offer "There were none" next to the right answer and ask the question again in a new context.', 'Draw a T-chart and fill the good side first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_EFFECTS.M_LG_IRON_NONE', 'SOCI.G6.PEOPLE.LANGUAGE_GROUPS_IN_EASTE.LG_EFFECTS', 'Does not know migration spread iron working.', '{"question":"Which skill did the Bantu spread as they migrated?","wrong_answer":"Making plastic","correct_answer":"Iron working"}'::jsonb, 'The child thinks iron tools came with Europeans.', 'Offer "Making plastic" next to the right answer and ask the question again in a new context.', 'Show a picture of a traditional smelting furnace.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_FACTORS.M_PD_PEOPLE_DESERT', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_FACTORS', 'Says many people live in deserts because land is cheap there.', '{"question":"Why do few people live in a desert?","wrong_answer":"Land is too cheap","correct_answer":"It is too dry to farm or find water"}'::jsonb, 'The child looks at land price, not at survival.', 'Offer "Land is too cheap" next to the right answer and ask the question again in a new context.', 'Ask where a family would find water and food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_FACTORS.M_PD_MOUNTAIN_TOP', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_FACTORS', 'Says people crowd on mountain tops because it is cool.', '{"question":"Which place is more likely to be crowded?","wrong_answer":"A steep, rocky mountain top","correct_answer":"Gentle land with fertile soil and rain"}'::jsonb, 'The child likes cool places and ignores farming.', 'Offer "A steep, rocky mountain top" next to the right answer and ask the question again in a new context.', 'Ask where it is easier to build and grow crops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_AREAS.M_PD_DENSITY_TOTAL', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_AREAS', 'Confuses density with total population: says the country with the most people has the highest density.', '{"question":"Density is the number of people for what?","wrong_answer":"The whole country","correct_answer":"Each square kilometre"}'::jsonb, 'The child thinks density is the same as population.', 'Offer "The whole country" next to the right answer and ask the question again in a new context.', 'Compare two countries by people per square kilometre in a small table.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_AREAS.M_PD_RWANDA_EMPTY', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_AREAS', 'Thinks Rwanda and Burundi are thinly populated because they are small.', '{"question":"Which country has high population density?","wrong_answer":"Somalia","correct_answer":"Rwanda"}'::jsonb, 'The child thinks small means few people.', 'Offer "Somalia" next to the right answer and ask the question again in a new context.', 'Give people and area for a small and a large country and divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_EFFECTS.M_PD_MORE_LAND', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_EFFECTS', 'Says high density means there is plenty of land for everyone.', '{"question":"What happens to farms when families grow large in a crowded area?","wrong_answer":"Farms get bigger","correct_answer":"Farms are divided into smaller plots"}'::jsonb, 'The child does not follow the land per person.', 'Offer "Farms get bigger" next to the right answer and ask the question again in a new context.', 'Cut a paper farm among more and more children.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_EFFECTS.M_PD_SERVICES', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_EFFECTS', 'Says crowding leaves schools and hospitals with too little work.', '{"question":"What pressure does a crowded area put on schools and hospitals?","wrong_answer":"They have too few learners and patients","correct_answer":"They have too many people to serve"}'::jsonb, 'The child confuses crowding with emptiness.', 'Offer "They have too few learners and patients" next to the right answer and ask the question again in a new context.', 'Count seats in a class of 90.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_FACTORS.M_PD_FACTORY_REPEL', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_FACTORS', 'Thinks factories and towns push people away because they are noisy.', '{"question":"Why do many people move to Nairobi and Kampala?","wrong_answer":"They do not; towns push people away","correct_answer":"For jobs, schools, hospitals and services"}'::jsonb, 'The child sees towns as crowded and unpleasant.', 'Offer "They do not; towns push people away" next to the right answer and ask the question again in a new context.', 'List what a town offers that a village may not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_FACTORS.M_PD_FOREST_DENSE', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_FACTORS', 'Thinks thick forests are crowded with people because there is plenty of food.', '{"question":"Are thick rain forests densely populated?","wrong_answer":"Yes, there is food everywhere","correct_answer":"No, they are hard to clear and travel through, and are often protected"}'::jsonb, 'The child links plenty of plants with plenty of people.', 'Offer "Yes, there is food everywhere" next to the right answer and ask the question again in a new context.', 'Compare the density map with the forest map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_AREAS.M_PD_BIG_COUNTRY_DENSE', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_AREAS', 'Thinks the biggest country must have the highest density.', '{"question":"Ethiopia is much bigger than Rwanda. Which has the higher density?","wrong_answer":"Ethiopia, it is bigger","correct_answer":"Rwanda"}'::jsonb, 'The child mixes size with crowding.', 'Offer "Ethiopia, it is bigger" next to the right answer and ask the question again in a new context.', 'Divide people by area for both, with rounded figures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_AREAS.M_PD_CITY_COUNTRY', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_AREAS', 'Thinks a whole country is crowded because its capital city is crowded.', '{"question":"Nairobi is crowded. Is all of Kenya densely populated?","wrong_answer":"Yes, the whole country","correct_answer":"No, northern Kenya is sparsely populated"}'::jsonb, 'The child takes the busiest place they know as the whole country.', 'Offer "Yes, the whole country" next to the right answer and ask the question again in a new context.', 'Shade Kenya on a density map: dark in some places, light in others.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_EFFECTS.M_PD_DENSE_NO_SLUMS', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_EFFECTS', 'Does not link high density in towns to slums.', '{"question":"Why do slums grow in crowded cities?","wrong_answer":"They do not","correct_answer":"There are more people than good, cheap houses"}'::jsonb, 'The child has not linked housing to population.', 'Offer "They do not" next to the right answer and ask the question again in a new context.', 'Count houses and families on a drawing of a growing town.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_EFFECTS.M_PD_FOREST_LOST', 'SOCI.G6.PEOPLE.POPULATION_DISTRIBUTION_.PD_EFFECTS', 'Does not see that crowding leads people to clear forests.', '{"question":"How can high population density harm forests?","wrong_answer":"It cannot","correct_answer":"People clear forests for farms, firewood and houses"}'::jsonb, 'The child keeps people and forests as separate topics.', 'Offer "It cannot" next to the right answer and ask the question again in a new context.', 'Show a before-and-after photo of a cleared hill.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_AGE.M_CS_SET_GROUP', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_AGE', 'Thinks an age-set is any group of children of the same age, like a class.', '{"question":"What makes people an age-set?","wrong_answer":"They were born in the same month","correct_answer":"They were initiated together"}'::jsonb, 'The child confuses age-set and age-group.', 'Offer "They were born in the same month" next to the right answer and ask the question again in a new context.', 'Say age-group means the same stage of life; age-set means initiated together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_AGE.M_CS_WARRIOR', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_AGE', 'Says the warrior age-set looked after the sick at home.', '{"question":"What was a main duty of the warrior age-set?","wrong_answer":"Looking after the sick at home","correct_answer":"Defending the community"}'::jsonb, 'The child gives the wrong duty.', 'Offer "Looking after the sick at home" next to the right answer and ask the question again in a new context.', 'Ask who guarded cattle and villages.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_CLAN.M_CS_MARRY_CLAN', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_CLAN', 'Says clan members should marry within their own clan.', '{"question":"Who could a person marry in a clan system?","wrong_answer":"Someone from the same clan","correct_answer":"Someone from a different clan"}'::jsonb, 'The child mixes up marriage with membership.', 'Offer "Someone from the same clan" next to the right answer and ask the question again in a new context.', 'Say clan members are like brothers and sisters.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_CLAN.M_CS_CLAN_FAMILY', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_CLAN', 'Thinks a clan is only one family.', '{"question":"What is a clan?","wrong_answer":"One family living in one home","correct_answer":"Many families with one ancestor"}'::jsonb, 'The child shrinks the clan to a household.', 'Offer "One family living in one home" next to the right answer and ask the question again in a new context.', 'Draw one ancestor with many branches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_PRESERVE.M_CS_ALL_GOOD', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_PRESERVE', 'Thinks every traditional custom should be kept.', '{"question":"Which custom should NOT be preserved?","wrong_answer":"Respect for elders","correct_answer":"Marrying girls off early and keeping them from school"}'::jsonb, 'The child thinks tradition is always right.', 'Offer "Respect for elders" next to the right answer and ask the question again in a new context.', 'Ask which customs help people and which harm them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_PRESERVE.M_CS_ALL_BAD', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_PRESERVE', 'Thinks all traditional culture is old-fashioned and should be dropped.', '{"question":"Which custom should be preserved?","wrong_answer":"None, they are all old-fashioned","correct_answer":"Respect for elders and community work"}'::jsonb, 'The child links old with bad.', 'Offer "None, they are all old-fashioned" next to the right answer and ask the question again in a new context.', 'Ask what proverbs and folktales teach.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_AGE.M_CS_GROUP_SET_SAME', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_AGE', 'Uses age-group and age-set as the same thing.', '{"question":"What is the difference between an age-group and an age-set?","wrong_answer":"There is none","correct_answer":"An age-group is people of about the same age; an age-set is those initiated together, who stay a group for life"}'::jsonb, 'The words sound alike.', 'Offer "There is none" next to the right answer and ask the question again in a new context.', 'Place cards: all the children of a village (age-group); boys initiated in one year (age-set).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_AGE.M_CS_ELDERS_NO_DUTY', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_AGE', 'Thinks elders had no duties in traditional society.', '{"question":"What did elders do in traditional societies?","wrong_answer":"Nothing, they rested","correct_answer":"Settled disputes, made decisions and led ceremonies"}'::jsonb, 'The child sees old age as rest.', 'Offer "Nothing, they rested" next to the right answer and ask the question again in a new context.', 'Act a council of elders hearing a case.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_CLAN.M_CS_CLAN_SAME_TRIBE', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_CLAN', 'Thinks a clan is the same as a whole community or tribe.', '{"question":"Is a clan the same as the whole community?","wrong_answer":"Yes","correct_answer":"No, a community has many clans"}'::jsonb, 'Both are groups of related people.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Draw a community circle with several clan circles inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_CLAN.M_CS_CLAN_NO_HELP', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_CLAN', 'Does not know clans helped members in need.', '{"question":"How did a clan help a family whose house burnt down?","wrong_answer":"It did not","correct_answer":"Members helped rebuild and gave food"}'::jsonb, 'The child thinks only of marriage rules.', 'Offer "It did not" next to the right answer and ask the question again in a new context.', 'Tell a story of clan members helping after a fire.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_PRESERVE.M_CS_HARM_HIDDEN', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_PRESERVE', 'Thinks a harmful practice is fine if done secretly.', '{"question":"A family plans to carry out FGM in secret. Is it acceptable?","wrong_answer":"Yes, if nobody knows","correct_answer":"No, it is harmful and against the law, secret or not"}'::jsonb, 'The child thinks the wrong is in being seen.', 'Offer "Yes, if nobody knows" next to the right answer and ask the question again in a new context.', 'Say plainly that FGM harms girls and is against the law, and name who to tell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_PRESERVE.M_CS_SONGS_STOP', 'SOCI.G6.PEOPLE.CULTURE_AND_SOCIAL_ORGAN.CS_PRESERVE', 'Thinks traditional songs and dances should stop because they are old.', '{"question":"Should traditional songs and dances be kept?","wrong_answer":"No, they are old-fashioned","correct_answer":"Yes, they keep our culture and are enjoyed today"}'::jsonb, 'The child links old with bad.', 'Offer "No, they are old-fashioned" next to the right answer and ask the question again in a new context.', 'Watch a music festival performance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_WAYS.M_SC_SCHOOL_ALONE', 'SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_WAYS', 'Counts something the school does alone as collaboration with the community.', '{"question":"Which is an example of the school working with the community?","wrong_answer":"Teachers marking books alone","correct_answer":"Parents helping to build a classroom"}'::jsonb, 'The child does not see that two parties must work together.', 'Offer "Teachers marking books alone" next to the right answer and ask the question again in a new context.', 'Ask: who else took part?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_WAYS.M_SC_ONE_WAY', 'SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_WAYS', 'Thinks only the community gives and the school gives nothing back.', '{"question":"What can a school give the community?","wrong_answer":"Nothing","correct_answer":"Its field, hall and educated learners"}'::jsonb, 'The child sees the school as a receiver.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Ask who votes in the school hall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_BENEFITS.M_SC_BENEFIT_ONLY_SCHOOL', 'SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_BENEFITS', 'Says collaboration benefits only the school.', '{"question":"Who gains when the school and community collaborate?","wrong_answer":"Only the school","correct_answer":"Both the school and the community"}'::jsonb, 'The child sees one side.', 'Offer "Only the school" next to the right answer and ask the question again in a new context.', 'Name one gain for each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_BENEFITS.M_SC_STRATEGY_STOP', 'SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_BENEFITS', 'Picks a strategy that ends collaboration (never meeting parents).', '{"question":"Which strategy keeps collaboration going?","wrong_answer":"Never inviting parents","correct_answer":"Holding open days and regular meetings"}'::jsonb, 'The child does not see what keeps a relationship alive.', 'Offer "Never inviting parents" next to the right answer and ask the question again in a new context.', 'Ask what happens if no one talks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_WAYS.M_SC_PARENTS_ONLY', 'SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_WAYS', 'Thinks only parents of current learners work with the school.', '{"question":"Who else in the community can work with the school besides parents?","wrong_answer":"Nobody","correct_answer":"Local leaders, religious groups, businesses, health workers and former learners"}'::jsonb, 'The child sees only parents at school events.', 'Offer "Nobody" next to the right answer and ask the question again in a new context.', 'List visitors to the school this term.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_WAYS.M_SC_FEES_ONLY', 'SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_WAYS', 'Thinks the only way the community helps is by paying money.', '{"question":"Give a way the community helps the school without money.","wrong_answer":"There is none","correct_answer":"Giving labour, security, advice or land"}'::jsonb, 'The child hears about fees more than other help.', 'Offer "There is none" next to the right answer and ask the question again in a new context.', 'Tell how parents built the school fence on a work day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_BENEFITS.M_SC_COMMUNITY_NO_GAIN', 'SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_BENEFITS', 'Does not see how the community gains from the school.', '{"question":"How does a community gain from a school?","wrong_answer":"It does not","correct_answer":"Educated learners, use of the hall and field, and health days"}'::jsonb, 'The child sees the school as only for learners.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'List community events held at school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_BENEFITS.M_SC_STRATEGY_OPEN_DAY', 'SOCI.G6.PEOPLE.SCHOOL_AND_COMMUNITY.SC_BENEFITS', 'Thinks an open day is for learners only and does not help the link with parents.', '{"question":"How does an open day help the school and the community work together?","wrong_answer":"It does not","correct_answer":"Parents meet teachers, see work and plan together"}'::jsonb, 'The child sees the open day as a learners'' show.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Ask what parents talked about with teachers at the last open day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_FACTORS.M_BF_RAIN_CROP', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_FACTORS', 'Says beef farming needs rich crop land with heavy rain.', '{"question":"Which area suits beef ranching best?","wrong_answer":"A small crop farm in a wet highland","correct_answer":"Large grassland with enough water"}'::jsonb, 'The child mixes crop farming with ranching.', 'Offer "A small crop farm in a wet highland" next to the right answer and ask the question again in a new context.', 'Ask what cattle eat and how much land they need.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_FACTORS.M_BF_DISEASE_NO', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_FACTORS', 'Thinks disease does not affect beef farming.', '{"question":"Why are vets important for beef farmers?","wrong_answer":"They are not important","correct_answer":"They control diseases that kill cattle"}'::jsonb, 'The child ignores risks.', 'Offer "They are not important" next to the right answer and ask the question again in a new context.', 'Ask what foot-and-mouth does to a herd.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_PLACES.M_BF_BEEF_COAST', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_PLACES', 'Puts the main beef areas in the cool, wet tea highlands.', '{"question":"Which area is known for beef ranching in Kenya?","wrong_answer":"The tea highlands of Kericho","correct_answer":"Laikipia and Kajiado"}'::jsonb, 'The child links Kenya to tea and not to ranches.', 'Offer "The tea highlands of Kericho" next to the right answer and ask the question again in a new context.', 'Ask which areas are dry grassland.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_PLACES.M_BF_SOMALIA', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_PLACES', 'Says Somalia exports no animals because it is dry.', '{"question":"What does Somalia export from its dry lands?","wrong_answer":"Fruit","correct_answer":"Live animals"}'::jsonb, 'The child does not know pastoral economies.', 'Offer "Fruit" next to the right answer and ask the question again in a new context.', 'Say animals feed on thorny bush and walk long distances to the port.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_ECONOMY.M_BF_MEAT_ONLY', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_ECONOMY', 'Says beef farming gives only meat.', '{"question":"What is made from the hides and skins of cattle?","wrong_answer":"Cooking oil","correct_answer":"Leather goods"}'::jsonb, 'The child names one product.', 'Offer "Cooking oil" next to the right answer and ask the question again in a new context.', 'List a product from each part of the animal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_ECONOMY.M_BF_NO_JOBS', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_ECONOMY', 'Says beef farming gives no jobs.', '{"question":"Who earns a living from the beef industry?","wrong_answer":"Nobody, it is just for food","correct_answer":"Herders, vets, butchers and factory workers"}'::jsonb, 'The child sees cattle but not the chain.', 'Offer "Nobody, it is just for food" next to the right answer and ask the question again in a new context.', 'Name every person from ranch to shop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_PROBLEMS.M_BF_SOLUTION_SWAP', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_PROBLEMS', 'Matches drought with dips or foot-and-mouth with boreholes.', '{"question":"What helps cattle during a long drought?","wrong_answer":"Dipping them","correct_answer":"Water pans, boreholes and hay"}'::jsonb, 'The child pairs challenge and solution wrongly.', 'Offer "Dipping them" next to the right answer and ask the question again in a new context.', 'Ask what the cattle lack: water and food, or cure for disease?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_PROBLEMS.M_BF_GRAZE_MORE', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_PROBLEMS', 'Thinks keeping more and more cattle solves overgrazing.', '{"question":"How can overgrazing be reduced?","wrong_answer":"Keep more cattle","correct_answer":"Rotate the grazing and keep fewer cattle"}'::jsonb, 'The child thinks more cattle means more money.', 'Offer "Keep more cattle" next to the right answer and ask the question again in a new context.', 'Show a field eaten bare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_FACTORS.M_BF_DAIRY_BEEF', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_FACTORS', 'Mixes up beef and dairy cattle, saying Friesians are the main beef breed.', '{"question":"Which breed is kept mainly for beef in Kenya?","wrong_answer":"Friesian","correct_answer":"Boran"}'::jsonb, 'Both are cattle and the child knows the dairy breed best.', 'Offer "Friesian" next to the right answer and ask the question again in a new context.', 'Compare photos of a Friesian (milk) and a Boran (beef).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_FACTORS.M_BF_MARKET_NONE', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_FACTORS', 'Thinks beef farming needs no market or roads.', '{"question":"Why does a beef farmer need roads?","wrong_answer":"They do not","correct_answer":"To take cattle or meat to market"}'::jsonb, 'The child thinks of cattle only on the farm.', 'Offer "They do not" next to the right answer and ask the question again in a new context.', 'Trace cattle from a ranch to the market and the meat factory.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_PLACES.M_BF_HIGHLAND_ONLY', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_PLACES', 'Thinks beef farming is done only in the highlands.', '{"question":"Is beef farming done on the dry plains of Kajiado?","wrong_answer":"No, only in the highlands","correct_answer":"Yes, on large grasslands"}'::jsonb, 'Dairy farming is in the highlands, and the child thinks all cattle are.', 'Offer "No, only in the highlands" next to the right answer and ask the question again in a new context.', 'Shade beef areas and dairy areas on the map in two colours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_PLACES.M_BF_ANKOLE_KENYA', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_PLACES', 'Places the Ankole cattle corridor in Kenya.', '{"question":"In which country is the Ankole cattle area?","wrong_answer":"Kenya","correct_answer":"Uganda"}'::jsonb, 'The child places all known cattle areas in Kenya.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Put Ankole on the map in south-western Uganda.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_ECONOMY.M_BF_HIDES_WASTE', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_ECONOMY', 'Thinks hides and skins are waste.', '{"question":"What are cattle hides used for?","wrong_answer":"Thrown away","correct_answer":"Making leather for shoes and bags"}'::jsonb, 'The child sees only the meat sold.', 'Offer "Thrown away" next to the right answer and ask the question again in a new context.', 'Show a leather shoe and trace it back to a hide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_ECONOMY.M_BF_NO_EXPORT', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_ECONOMY', 'Thinks Eastern African beef is never sold abroad.', '{"question":"Do Eastern African countries sell beef and live animals abroad?","wrong_answer":"No, it is all eaten at home","correct_answer":"Yes, and this earns foreign exchange"}'::jsonb, 'The child sees meat only at the butchery.', 'Offer "No, it is all eaten at home" next to the right answer and ask the question again in a new context.', 'Show live animals shipped from Berbera or Somalia ports (to confirm).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_PROBLEMS.M_BF_RUSTLING_DIP', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_PROBLEMS', 'Matches cattle rustling with dipping.', '{"question":"Which solution fits cattle rustling?","wrong_answer":"Dipping the cattle","correct_answer":"Better security and peace committees"}'::jsonb, 'Dips are a well-known cattle solution.', 'Offer "Dipping the cattle" next to the right answer and ask the question again in a new context.', 'Pair each problem with the cause: theft needs security, ticks need dips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.BEEF_FARMING.BF_PROBLEMS.M_BF_PRICE_MORE_COWS', 'SOCI.G6.RESOUR.BEEF_FARMING.BF_PROBLEMS', 'Thinks low prices are solved by keeping more cattle.', '{"question":"Beef prices are low. What helps farmers?","wrong_answer":"Keep more cattle","correct_answer":"Better markets, co-operatives and meat processing"}'::jsonb, 'More seems better.', 'Offer "Keep more cattle" next to the right answer and ask the question again in a new context.', 'Ask what happens to price when everyone brings more cattle to market.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_GROUNDS.M_FI_LAKE_SEA', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_GROUNDS', 'Says Lake Victoria is a marine fishing ground.', '{"question":"Which is a marine fishing ground?","wrong_answer":"Lake Victoria","correct_answer":"The Indian Ocean coast"}'::jsonb, 'The child thinks any big water is the sea.', 'Offer "Lake Victoria" next to the right answer and ask the question again in a new context.', 'Ask whether the water is salty or fresh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_GROUNDS.M_FI_FISH_PLACE', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_GROUNDS', 'Says Nile perch comes from the Indian Ocean.', '{"question":"Which fish comes from Lake Victoria?","wrong_answer":"Tuna","correct_answer":"Nile perch"}'::jsonb, 'The child mixes the fish and the water.', 'Offer "Tuna" next to the right answer and ask the question again in a new context.', 'Match fish and water in a small table.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_METHODS.M_FI_TRAWL', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_METHODS', 'Says trawling means fishing with a hook and line.', '{"question":"What is trawling?","wrong_answer":"Fishing with a hook and line","correct_answer":"Dragging a net behind a boat"}'::jsonb, 'The child mixes the names.', 'Offer "Fishing with a hook and line" next to the right answer and ask the question again in a new context.', 'Say trawl means to drag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_METHODS.M_FI_TRAD_MODERN', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_METHODS', 'Says dug-out canoes with baskets are a modern method.', '{"question":"Which is a modern method of fishing?","wrong_answer":"A basket trap from a canoe","correct_answer":"A trawler with a cold room"}'::jsonb, 'The child cannot tell old from new.', 'Offer "A basket trap from a canoe" next to the right answer and ask the question again in a new context.', 'Ask which has an engine and a freezer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_PROBLEMS.M_FI_OVER_OK', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_PROBLEMS', 'Says catching as many fish as possible is always good for fishing.', '{"question":"What does overfishing cause?","wrong_answer":"More fish every year","correct_answer":"Fish stocks fall"}'::jsonb, 'The child thinks more catching means more fish.', 'Offer "More fish every year" next to the right answer and ask the question again in a new context.', 'Ask what happens if you take all the eggs and young fish.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_PROBLEMS.M_FI_SOLUTION_MIX', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_PROBLEMS', 'Pairs piracy with cold rooms or poor storage with patrols.', '{"question":"What helps fish keep fresh before sale?","wrong_answer":"Sea patrols","correct_answer":"Cold rooms and processing plants"}'::jsonb, 'The child mixes challenge and answer.', 'Offer "Sea patrols" next to the right answer and ask the question again in a new context.', 'Ask what spoils fish: thieves or heat?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_GROUNDS.M_FI_TANGANYIKA_KENYA', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_GROUNDS', 'Places Lake Tanganyika in Kenya.', '{"question":"Is Lake Tanganyika in Kenya?","wrong_answer":"Yes","correct_answer":"No, it is on the borders of Tanzania, Burundi, DR Congo and Zambia"}'::jsonb, 'The name sounds like Tanzania and the child guesses East Africa means Kenya.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Find the lake on the regional map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_GROUNDS.M_FI_MARINE_MEANS_LAKE', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_GROUNDS', 'Thinks marine means any large water body.', '{"question":"What does \"marine fishing\" mean?","wrong_answer":"Fishing in any big water","correct_answer":"Fishing in the sea or ocean"}'::jsonb, 'The child has not met the word marine.', 'Offer "Fishing in any big water" next to the right answer and ask the question again in a new context.', 'Write marine = sea beside a picture of the Indian Ocean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_METHODS.M_FI_PURSE_SEINE', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_METHODS', 'Thinks a purse seine is a small bag for carrying fish.', '{"question":"What is a purse seine?","wrong_answer":"A bag to carry fish home","correct_answer":"A big net that circles a shoal and is pulled closed at the bottom"}'::jsonb, 'The word purse makes the child think of a small bag.', 'Offer "A bag to carry fish home" next to the right answer and ask the question again in a new context.', 'Draw the net circling the fish and closing like a drawstring purse.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_METHODS.M_FI_MODERN_SMALL', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_METHODS', 'Thinks modern fishing catches less than traditional fishing.', '{"question":"Which catches more fish: a trawler or a canoe with a basket?","wrong_answer":"The canoe","correct_answer":"The trawler"}'::jsonb, 'The child links old with plentiful.', 'Offer "The canoe" next to the right answer and ask the question again in a new context.', 'Compare the size of a trawler net and a basket.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_PROBLEMS.M_FI_WEED_GOOD', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_PROBLEMS', 'Thinks water hyacinth helps fishing because fish hide in it.', '{"question":"How does water hyacinth on Lake Victoria affect fishing?","wrong_answer":"It helps; fish hide in it","correct_answer":"It blocks boats and reduces oxygen for fish"}'::jsonb, 'The child sees plants as homes for fish.', 'Offer "It helps; fish hide in it" next to the right answer and ask the question again in a new context.', 'Show a photo of boats stuck in hyacinth at Kisumu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_PROBLEMS.M_FI_STORAGE_SALT', 'SOCI.G6.RESOUR.FISHING_IN_EASTERN_AFRIC.FI_PROBLEMS', 'Does not see poor storage as a problem, thinking fish keep for days in the sun.', '{"question":"Why do some fishers lose fish before selling them?","wrong_answer":"They do not; fish keep for days","correct_answer":"Fish go bad quickly without ice or cold rooms"}'::jsonb, 'The child does not know how fast fish spoil.', 'Offer "They do not; fish keep for days" next to the right answer and ask the question again in a new context.', 'Compare dried fish with fresh fish left out for a day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_FACTORS.M_WT_TOURIST_ROADS', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_FACTORS', 'Says tourism does not need roads, airports or hotels.', '{"question":"What do airports and hotels do for tourism?","wrong_answer":"Nothing","correct_answer":"Help visitors to arrive and stay"}'::jsonb, 'The child sees only the animals.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Follow a tourist from home to the park.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_FACTORS.M_WT_INSECURITY', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_FACTORS', 'Says insecurity makes more tourists come.', '{"question":"What does insecurity do to tourism?","wrong_answer":"Brings more tourists","correct_answer":"Frightens tourists away"}'::jsonb, 'The child has not linked fear to travel.', 'Offer "Brings more tourists" next to the right answer and ask the question again in a new context.', 'Ask whether a family would visit an unsafe place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PARKS.M_WT_PARK_COUNTRY', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PARKS', 'Puts the Serengeti in Kenya or the Maasai Mara in Tanzania.', '{"question":"In which country is the Serengeti National Park?","wrong_answer":"Kenya","correct_answer":"Tanzania"}'::jsonb, 'The child knows the migration but not the border.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Say Serengeti is south of the border and Mara is north.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PARKS.M_WT_GORILLA', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PARKS', 'Says mountain gorillas are seen in the Maasai Mara.', '{"question":"Where can mountain gorillas be seen?","wrong_answer":"The Maasai Mara","correct_answer":"Bwindi in Uganda and Volcanoes in Rwanda"}'::jsonb, 'The child knows big wildlife only on the plains.', 'Offer "The Maasai Mara" next to the right answer and ask the question again in a new context.', 'Say gorillas live in forest on mountains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PROBLEMS.M_WT_POACH_OK', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PROBLEMS', 'Says poaching helps tourism because it brings money to the poacher.', '{"question":"What does poaching do to tourism?","wrong_answer":"Helps it grow","correct_answer":"Kills the wildlife tourists come to see"}'::jsonb, 'The child sees only the poacher''s gain.', 'Offer "Helps it grow" next to the right answer and ask the question again in a new context.', 'Ask what is left to see if animals are killed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PROBLEMS.M_WT_SOLUTION_SWAP', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PROBLEMS', 'Pairs poaching with road building.', '{"question":"What helps to stop poaching?","wrong_answer":"Building roads","correct_answer":"Anti-poaching patrols and strong laws"}'::jsonb, 'The child mixes challenge and answer.', 'Offer "Building roads" next to the right answer and ask the question again in a new context.', 'Ask which answer stops a poacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_FACTORS.M_WT_ANIMALS_ONLY_FACTOR', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_FACTORS', 'Thinks wildlife alone is enough to bring tourists.', '{"question":"A country has many animals but no roads or hotels near the park. Will many tourists come?","wrong_answer":"Yes, animals are enough","correct_answer":"No, tourists also need roads, hotels and security"}'::jsonb, 'The child sees only the attraction, not the services.', 'Offer "Yes, animals are enough" next to the right answer and ask the question again in a new context.', 'Plan a trip: list what you need besides the animals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_FACTORS.M_WT_CLIMATE_NONE', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_FACTORS', 'Does not see a pleasant climate as a factor in tourism.', '{"question":"Why do many tourists come in the dry season?","wrong_answer":"There is no reason","correct_answer":"Animals are easier to see and roads are easier to use"}'::jsonb, 'The child does not link weather to travel.', 'Offer "There is no reason" next to the right answer and ask the question again in a new context.', 'Compare a muddy road in the rains with a dry one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PARKS.M_WT_NGORONGORO_KENYA', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PARKS', 'Places Ngorongoro Crater in Kenya.', '{"question":"In which country is the Ngorongoro Crater?","wrong_answer":"Kenya","correct_answer":"Tanzania"}'::jsonb, 'The child places the famous parks in Kenya.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Pin each park on the regional map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PARKS.M_WT_PARK_SAME_ANIMALS', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PARKS', 'Thinks every park has the same animals.', '{"question":"Where in Eastern Africa can mountain gorillas be seen?","wrong_answer":"In every park","correct_answer":"In Bwindi (Uganda) and the Volcanoes National Park (Rwanda)"}'::jsonb, 'The child thinks all parks hold all animals.', 'Offer "In every park" next to the right answer and ask the question again in a new context.', 'Show the gorilla range on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PROBLEMS.M_WT_CONFLICT_KILL', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PROBLEMS', 'Thinks killing wild animals solves human-wildlife conflict.', '{"question":"Elephants destroy crops near a park. What is a good solution?","wrong_answer":"Kill the elephants","correct_answer":"Electric fences, chilli or beehive fences and compensation"}'::jsonb, 'Removing the animal seems simplest.', 'Offer "Kill the elephants" next to the right answer and ask the question again in a new context.', 'Show a beehive fence that keeps elephants out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PROBLEMS.M_WT_ADVERT_NONE', 'SOCI.G6.RESOUR.WILDLIFE_AND_TOURISM_IN_.WT_PROBLEMS', 'Does not see marketing as a need for tourism.', '{"question":"How can a country bring more tourists?","wrong_answer":"Do nothing","correct_answer":"Advertise its attractions abroad and at home"}'::jsonb, 'The child thinks tourists find out by themselves.', 'Offer "Do nothing" next to the right answer and ask the question again in a new context.', 'Show a tourism advert.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_NETWORKS.M_TR_PORT_COUNTRY', 'SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_NETWORKS', 'Puts Mombasa in Tanzania or Dar es Salaam in Kenya.', '{"question":"In which country is the port of Dar es Salaam?","wrong_answer":"Kenya","correct_answer":"Tanzania"}'::jsonb, 'The child mixes the two ports.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Match port and country in a small table.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_NETWORKS.M_TR_MODE_LOAD', 'SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_NETWORKS', 'Says heavy goods are best sent by air.', '{"question":"Which mode suits bulky heavy goods over a long distance?","wrong_answer":"Air","correct_answer":"Railway"}'::jsonb, 'The child likes the fastest mode.', 'Offer "Air" next to the right answer and ask the question again in a new context.', 'Ask about the cost of flying a lorry load.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_NETWORKS.M_TR_LANDLOCKED_PORT', 'SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_NETWORKS', 'Says landlocked Uganda has its own sea port.', '{"question":"Which port does Uganda use for most of its imports?","wrong_answer":"It has its own","correct_answer":"Mombasa"}'::jsonb, 'The child forgets Uganda is landlocked.', 'Offer "It has its own" next to the right answer and ask the question again in a new context.', 'Trace the road from Kampala to the sea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_PROBLEMS.M_TR_BORDER', 'SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_PROBLEMS', 'Says one-stop border posts make delays longer.', '{"question":"What does a one-stop border post do?","wrong_answer":"Makes lorries wait longer","correct_answer":"Lets officials of both countries check once"}'::jsonb, 'The child does not know what it does.', 'Offer "Makes lorries wait longer" next to the right answer and ask the question again in a new context.', 'Ask what one stop means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_PROBLEMS.M_TR_CRASH_SOLVE', 'SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_PROBLEMS', 'Thinks more speed fixes road crashes.', '{"question":"What helps reduce road crashes?","wrong_answer":"Higher speeds","correct_answer":"Speed limits and driver training"}'::jsonb, 'The child thinks faster is better.', 'Offer "Higher speeds" next to the right answer and ask the question again in a new context.', 'Ask what happens when a car hits at high speed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_NETWORKS.M_TR_TAZARA_KENYA', 'SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_NETWORKS', 'Thinks the TAZARA railway runs through Kenya.', '{"question":"Which countries does the TAZARA railway join?","wrong_answer":"Kenya and Uganda","correct_answer":"Tanzania and Zambia"}'::jsonb, 'The child places every railway in Kenya.', 'Offer "Kenya and Uganda" next to the right answer and ask the question again in a new context.', 'Trace TAZARA from Dar es Salaam to Zambia on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_PROBLEMS.M_TR_BORDER_NO_PROBLEM', 'SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_PROBLEMS', 'Thinks border crossings never slow down goods.', '{"question":"Why do lorries sometimes wait days at a border?","wrong_answer":"They never wait","correct_answer":"Paperwork, checks and queues at the border"}'::jsonb, 'The child has not seen a border.', 'Offer "They never wait" next to the right answer and ask the question again in a new context.', 'Describe a queue of lorries at Malaba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_PROBLEMS.M_TR_VANDAL_HARMLESS', 'SOCI.G6.RESOUR.TRANSPORT_IN_EASTERN_AFR.TR_PROBLEMS', 'Thinks stealing railway parts or road signs is harmless.', '{"question":"How does stealing road signs affect transport?","wrong_answer":"It does not","correct_answer":"Drivers miss warnings and accidents happen"}'::jsonb, 'The child sees only the value of the metal.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Show a bend with and without a warning sign.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_MODES.M_CM_TRAD_MODERN', 'SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_MODES', 'Calls drums a modern mode of communication.', '{"question":"Which is a traditional way of communicating?","wrong_answer":"The mobile phone","correct_answer":"The drum"}'::jsonb, 'The child mixes old and new.', 'Offer "The mobile phone" next to the right answer and ask the question again in a new context.', 'Ask which needs electricity.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_MODES.M_CM_MASS', 'SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_MODES', 'Says a letter reaches many people at the same moment.', '{"question":"Which mode reaches many people at once?","wrong_answer":"A letter","correct_answer":"Radio"}'::jsonb, 'The child does not tell one-to-one and mass.', 'Offer "A letter" next to the right answer and ask the question again in a new context.', 'Ask who hears a radio in a village.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_PROBLEMS.M_CM_ELEC', 'SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_PROBLEMS', 'Says electricity has nothing to do with communication.', '{"question":"Why does lack of electricity harm communication?","wrong_answer":"It does not","correct_answer":"Phones, radio and the internet need power"}'::jsonb, 'The child ignores the power link.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Ask how a phone is charged.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_PROBLEMS.M_CM_SOLUTION_SWAP', 'SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_PROBLEMS', 'Pairs vandalism with lack of training.', '{"question":"What helps to stop theft of masts and cables?","wrong_answer":"Training in digital skills","correct_answer":"Laws and guards"}'::jsonb, 'The child mixes challenge and answer.', 'Offer "Training in digital skills" next to the right answer and ask the question again in a new context.', 'Ask which action stops a thief.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_MODES.M_CM_PHONE_MASS', 'SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_MODES', 'Thinks a phone call is mass communication.', '{"question":"Is a phone call between two friends mass communication?","wrong_answer":"Yes","correct_answer":"No, it is between two people; radio and television are mass media"}'::jsonb, 'The child knows phones are modern and assumes they reach many.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Sort modes into one-to-one and one-to-many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_MODES.M_CM_INTERNET_ONE', 'SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_MODES', 'Thinks the internet is only for games.', '{"question":"Give one use of the internet for communication.","wrong_answer":"Only games","correct_answer":"Email, news and messages"}'::jsonb, 'The child has seen children use phones for games.', 'Offer "Only games" next to the right answer and ask the question again in a new context.', 'Show an email and a news website.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_PROBLEMS.M_CM_COST_NONE', 'SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_PROBLEMS', 'Does not see cost as a challenge to communication.', '{"question":"Why do some families not use the internet?","wrong_answer":"Everyone uses it","correct_answer":"It costs money for data and phones"}'::jsonb, 'The child''s family may have access.', 'Offer "Everyone uses it" next to the right answer and ask the question again in a new context.', 'Compare the cost of data with the cost of a loaf of bread.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_PROBLEMS.M_CM_FAKE_NEWS_NONE', 'SOCI.G6.RESOUR.COMMUNICATIO_N_IN_EASTER.CM_PROBLEMS', 'Does not see false news as a challenge.', '{"question":"A message says a school is closed, but it is not true. What problem is this?","wrong_answer":"No problem","correct_answer":"False news, which misleads people"}'::jsonb, 'The child trusts messages.', 'Offer "No problem" next to the right answer and ask the question again in a new context.', 'Check the message against the school''s own notice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_MINERALS.M_MN_MINERAL_PLACE', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_MINERALS', 'Puts soda ash in Tanzania and gold only in Kenya.', '{"question":"Where is soda ash mined in Kenya?","wrong_answer":"Lake Naivasha","correct_answer":"Lake Magadi"}'::jsonb, 'The child mixes lake names.', 'Offer "Lake Naivasha" next to the right answer and ask the question again in a new context.', 'Ask which lake is salty and in the south of the Rift.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_MINERALS.M_MN_TANZANITE', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_MINERALS', 'Says tanzanite is mined in Kenya or Uganda.', '{"question":"Which country mines tanzanite?","wrong_answer":"Kenya","correct_answer":"Tanzania"}'::jsonb, 'The child does not link the name to the country.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Say tanzanite takes its name from the country.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_MINERALS.M_MN_NOT_MINERAL', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_MINERALS', 'Counts a crop or timber as a mineral.', '{"question":"Which is a mineral?","wrong_answer":"Coffee","correct_answer":"Limestone"}'::jsonb, 'The child treats any resource as a mineral.', 'Offer "Coffee" next to the right answer and ask the question again in a new context.', 'Ask: dug from the ground or grown?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_METHODS.M_MN_METHOD_SWAP', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_METHODS', 'Says limestone is mined by going down a deep shaft.', '{"question":"How is limestone usually mined?","wrong_answer":"In deep underground shafts","correct_answer":"In an open pit or quarry"}'::jsonb, 'The child pictures every mine as a tunnel.', 'Offer "In deep underground shafts" next to the right answer and ask the question again in a new context.', 'Show a quarry at the coast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_METHODS.M_MN_PANNING', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_METHODS', 'Says panning uses machines and blasting.', '{"question":"What is panning?","wrong_answer":"Blasting rock with explosives","correct_answer":"Washing gravel in water to find mineral bits"}'::jsonb, 'The child mixes the methods.', 'Offer "Blasting rock with explosives" next to the right answer and ask the question again in a new context.', 'Ask what a pan and water can do to find gold.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_EFFECTS.M_MN_NO_HARM', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_EFFECTS', 'Says mining never harms the land.', '{"question":"What does open-cast mining leave behind?","wrong_answer":"Nothing","correct_answer":"Large holes and bare land"}'::jsonb, 'The child sees the mineral and not the hole.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Show a quarry photograph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_EFFECTS.M_MN_REPAIR', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_EFFECTS', 'Says the best repair for a mine is to leave the pit open.', '{"question":"How can a mined area be repaired?","wrong_answer":"Leave the pit open","correct_answer":"Refill it and plant trees"}'::jsonb, 'The child does not know reclamation.', 'Offer "Leave the pit open" next to the right answer and ask the question again in a new context.', 'Talk about Haller Park in Mombasa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_MINERALS.M_MN_OIL_NOT_MINERAL', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_MINERALS', 'Does not count oil as a mineral resource.', '{"question":"Is the oil found in Turkana a mineral resource?","wrong_answer":"No, it is a liquid","correct_answer":"Yes, it is a mineral resource"}'::jsonb, 'The child pictures minerals as rocks.', 'Offer "No, it is a liquid" next to the right answer and ask the question again in a new context.', 'List minerals in all forms: solid (gold), liquid (oil).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_METHODS.M_MN_SODA_DREDGE', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_METHODS', 'Thinks soda ash is dug from deep shafts.', '{"question":"How is soda ash taken from Lake Magadi?","wrong_answer":"From deep shafts","correct_answer":"Dredged or scooped from the lake surface"}'::jsonb, 'The child thinks all mining goes underground.', 'Offer "From deep shafts" next to the right answer and ask the question again in a new context.', 'Show a photo of the white crust on Lake Magadi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_METHODS.M_MN_OPEN_CAST_DEEP', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_METHODS', 'Thinks open-cast mining means a narrow, deep tunnel.', '{"question":"What is open-cast mining?","wrong_answer":"A narrow deep tunnel","correct_answer":"Digging a big open pit from the surface"}'::jsonb, 'Mining is pictured as tunnels.', 'Offer "A narrow deep tunnel" next to the right answer and ask the question again in a new context.', 'Compare a quarry photo with a tunnel drawing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_EFFECTS.M_MN_MERCURY', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_EFFECTS', 'Does not know chemicals from mining can poison rivers.', '{"question":"How can small gold mines harm rivers?","wrong_answer":"They cannot","correct_answer":"Mercury used for gold can poison the water"}'::jsonb, 'The child sees mining as only digging.', 'Offer "They cannot" next to the right answer and ask the question again in a new context.', 'Show a picture of a warning sign at a polluted river.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_EFFECTS.M_MN_JOBS_ONLY', 'SOCI.G6.RESOUR.MINING_IN_EASTERN_AFRICA.MN_EFFECTS', 'Lists only good effects of mining.', '{"question":"Give one bad effect of mining.","wrong_answer":"There are none; mining gives jobs","correct_answer":"Dust, noise, open pits or polluted water"}'::jsonb, 'The child stops at the benefits.', 'Offer "There are none; mining gives jobs" next to the right answer and ask the question again in a new context.', 'Use a T-chart with both sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_BUGANDA.M_TG_KABAKA', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_BUGANDA', 'Says the ruler of Buganda was the Ntemi.', '{"question":"What was the ruler of Buganda called?","wrong_answer":"Ntemi","correct_answer":"Kabaka"}'::jsonb, 'The child mixes the two titles.', 'Offer "Ntemi" next to the right answer and ask the question again in a new context.', 'Match Buganda with Kabaka and Nyamwezi with Ntemi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_BUGANDA.M_TG_KATIKKIRO', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_BUGANDA', 'Says the Katikkiro was the chief of a village or a priest.', '{"question":"Who was the Katikkiro?","wrong_answer":"The village priest","correct_answer":"The chief minister"}'::jsonb, 'The child has not heard the word.', 'Offer "The village priest" next to the right answer and ask the question again in a new context.', 'Say the Katikkiro was the Kabaka''s main helper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_NYAMWEZI.M_TG_NTEMI_KING', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_NYAMWEZI', 'Says the Nyamwezi had one large kingdom.', '{"question":"How was the Nyamwezi land organised?","wrong_answer":"One large kingdom under one king","correct_answer":"Many small chiefdoms each under a Ntemi"}'::jsonb, 'The child mixes it with Buganda.', 'Offer "One large kingdom under one king" next to the right answer and ask the question again in a new context.', 'Count the chiefdoms on a sketch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_NYAMWEZI.M_TG_NTEMI_CHOSEN', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_NYAMWEZI', 'Says a Ntemi was voted for by all the people.', '{"question":"How did a person become a Ntemi?","wrong_answer":"By a vote of all the people","correct_answer":"By inheriting the position"}'::jsonb, 'The child applies modern elections.', 'Offer "By a vote of all the people" next to the right answer and ask the question again in a new context.', 'Say the position passed in the royal family.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_COMPARE.M_TG_SAME_ALL', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_COMPARE', 'Says the two systems were exactly the same.', '{"question":"How did the Buganda system differ from the Nyamwezi?","wrong_answer":"It did not differ","correct_answer":"Buganda was one big centralised kingdom"}'::jsonb, 'The child sees only the likeness.', 'Offer "It did not differ" next to the right answer and ask the question again in a new context.', 'Say how many rulers each system had.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_COMPARE.M_TG_NO_COUNCIL', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_COMPARE', 'Says only one of the two had a council or advisers.', '{"question":"What did both have in common?","wrong_answer":"Neither had advisers","correct_answer":"A ruler who was advised by a council"}'::jsonb, 'The child thinks one system was simple.', 'Offer "Neither had advisers" next to the right answer and ask the question again in a new context.', 'Name the council in each: Lukiiko and council of elders.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_BUGANDA.M_TG_LUKIIKO_ARMY', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_BUGANDA', 'Thinks the Lukiiko was the Buganda army.', '{"question":"What was the Lukiiko?","wrong_answer":"The army","correct_answer":"The council (parliament) of Buganda"}'::jsonb, 'The child guesses from a strange word.', 'Offer "The army" next to the right answer and ask the question again in a new context.', 'Write each title with its job on cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_BUGANDA.M_TG_KABAKA_ELECTED', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_BUGANDA', 'Thinks the Kabaka was elected by all the people.', '{"question":"How did a person become Kabaka?","wrong_answer":"By a vote of all the people","correct_answer":"By inheriting it in the royal family"}'::jsonb, 'The child uses modern elections as the model.', 'Offer "By a vote of all the people" next to the right answer and ask the question again in a new context.', 'Compare with how a President is chosen today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_NYAMWEZI.M_TG_NTEMI_ALONE', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_NYAMWEZI', 'Thinks the Ntemi ruled without any advisers.', '{"question":"Who advised the Ntemi?","wrong_answer":"Nobody","correct_answer":"A council of elders"}'::jsonb, 'The child pictures a chief as ruling alone.', 'Offer "Nobody" next to the right answer and ask the question again in a new context.', 'Act a Ntemi consulting elders before deciding.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_NYAMWEZI.M_TG_NYAMWEZI_KENYA', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_NYAMWEZI', 'Places the Nyamwezi in Kenya.', '{"question":"In which country do the Nyamwezi live?","wrong_answer":"Kenya","correct_answer":"Tanzania"}'::jsonb, 'The child places most communities in Kenya.', 'Offer "Kenya" next to the right answer and ask the question again in a new context.', 'Point to central Tanzania on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_COMPARE.M_TG_SIZE_SWAP', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_COMPARE', 'Thinks the Nyamwezi had one big kingdom and Buganda had many small chiefdoms.', '{"question":"Which had many small chiefdoms: Buganda or the Nyamwezi?","wrong_answer":"Buganda","correct_answer":"The Nyamwezi"}'::jsonb, 'The two systems are learnt together and swapped.', 'Offer "Buganda" next to the right answer and ask the question again in a new context.', 'Draw one big circle for Buganda and many small ones for the Nyamwezi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_COMPARE.M_TG_CHIEFS_INHERIT', 'SOCI.G6.POLITI.TRADITIONAL_FORMS_OF_GOV.TG_COMPARE', 'Thinks Buganda''s county chiefs inherited their posts like the Ntemi.', '{"question":"How did Buganda''s county chiefs get their posts?","wrong_answer":"They inherited them","correct_answer":"The Kabaka appointed them"}'::jsonb, 'Both systems had chiefs.', 'Offer "They inherited them" next to the right answer and ask the question again in a new context.', 'Sort "appointed" and "inherited" for each title.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_OBJECTIVES.M_RC_HQ', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_OBJECTIVES', 'Puts the EAC headquarters in Nairobi or Kampala.', '{"question":"Where is the EAC headquarters?","wrong_answer":"Nairobi","correct_answer":"Arusha"}'::jsonb, 'The child names the biggest city.', 'Offer "Nairobi" next to the right answer and ask the question again in a new context.', 'Say Arusha is near Kilimanjaro in Tanzania.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_OBJECTIVES.M_RC_CUSTOMS', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_OBJECTIVES', 'Says a customs union means each country charges its own duty to its partners.', '{"question":"What does a customs union do?","wrong_answer":"Each country taxes goods from partners","correct_answer":"Partners trade without duty and share one outside tariff"}'::jsonb, 'The child does not know the word customs.', 'Offer "Each country taxes goods from partners" next to the right answer and ask the question again in a new context.', 'Say customs duty is a tax on goods that cross a border.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_BENEFITS.M_RC_BENEFIT_ONE', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_BENEFITS', 'Says the EAC benefits only the biggest country.', '{"question":"Who gains from a common market?","wrong_answer":"Only the biggest country","correct_answer":"All member countries and their people"}'::jsonb, 'The child thinks size wins.', 'Offer "Only the biggest country" next to the right answer and ask the question again in a new context.', 'List a gain for a small and a large partner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_BENEFITS.M_RC_NO_MOVE', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_BENEFITS', 'Says people cannot move to work in another EAC country.', '{"question":"What does the common market allow?","wrong_answer":"No movement of workers","correct_answer":"Free movement of people, goods and services"}'::jsonb, 'The child does not know the common market.', 'Offer "No movement of workers" next to the right answer and ask the question again in a new context.', 'Say the market includes labour as well as goods.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_PROBLEMS.M_RC_PROBLEM_SOLUTION', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_PROBLEMS', 'Pairs border delays with a common anthem.', '{"question":"What helps to reduce delays at borders?","wrong_answer":"Singing the anthem","correct_answer":"One-stop border posts"}'::jsonb, 'The child mixes the answers.', 'Offer "Singing the anthem" next to the right answer and ask the question again in a new context.', 'Ask which answer speeds lorries.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_PROBLEMS.M_RC_WAR', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_PROBLEMS', 'Says disputes between member countries should be settled by force.', '{"question":"How should disputes between partner states be settled?","wrong_answer":"By force","correct_answer":"By talks and the EAC Court of Justice"}'::jsonb, 'The child thinks force settles a dispute.', 'Offer "By force" next to the right answer and ask the question again in a new context.', 'Say the community is built on peace.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_OBJECTIVES.M_RC_ONE_COUNTRY', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_OBJECTIVES', 'Thinks the EAC has already made its members into one country.', '{"question":"Are EAC members now one country?","wrong_answer":"Yes","correct_answer":"No, they are separate countries working together"}'::jsonb, 'Political federation is listed as an aim and taken as done.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Show that each member still has its own president and flag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_OBJECTIVES.M_RC_MONETARY_DONE', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_OBJECTIVES', 'Thinks EAC countries already use one currency.', '{"question":"Do EAC countries use one currency today?","wrong_answer":"Yes, the same money","correct_answer":"No, each has its own; a single currency is a future aim"}'::jsonb, 'The child hears "monetary union" as done.', 'Offer "Yes, the same money" next to the right answer and ask the question again in a new context.', 'Show a Kenyan shilling and a Tanzanian shilling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_BENEFITS.M_RC_DUTY_ALL', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_BENEFITS', 'Thinks goods traded inside the EAC pay the same duty as goods from other continents.', '{"question":"Do goods made in Kenya pay customs duty in Uganda?","wrong_answer":"Yes, the same as goods from anywhere","correct_answer":"Mostly no, because of the customs union"}'::jsonb, 'The child does not know what a customs union does.', 'Offer "Yes, the same as goods from anywhere" next to the right answer and ask the question again in a new context.', 'Act a lorry crossing a border with and without duty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_BENEFITS.M_RC_STUDY_NONE', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_BENEFITS', 'Thinks a Kenyan learner cannot study in another EAC country.', '{"question":"Can a Kenyan student study at a university in Uganda?","wrong_answer":"No","correct_answer":"Yes, many do"}'::jsonb, 'The child thinks borders stop study.', 'Offer "No" next to the right answer and ask the question again in a new context.', 'Tell of Kenyan students in Kampala universities.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_PROBLEMS.M_RC_LEAVE_SOLVE', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_PROBLEMS', 'Thinks a member should leave the EAC at the first disagreement.', '{"question":"Two members disagree about trade. What is the best step?","wrong_answer":"Leave the EAC","correct_answer":"Talk it through and use the EAC''s own bodies to settle it"}'::jsonb, 'The child sees leaving as the end of the problem.', 'Offer "Leave the EAC" next to the right answer and ask the question again in a new context.', 'Recall that the first EAC collapsed in 1977 and members lost the benefits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_PROBLEMS.M_RC_UNEQUAL_FINE', 'SOCI.G6.POLITI.REGIONAL_CO_OPERATIONS.RC_PROBLEMS', 'Thinks unequal benefits are not a problem.', '{"question":"Why can unequal benefits harm the EAC?","wrong_answer":"They cannot","correct_answer":"Members that gain less may feel cheated and lose trust"}'::jsonb, 'The child does not see fairness as part of co-operation.', 'Offer "They cannot" next to the right answer and ask the question again in a new context.', 'Share a prize unfairly in a group game and talk about it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.CITIZENSHIP.CZ_RIGHTS_RESP.M_CZ_RIGHT_RESP', 'SOCI.G6.POLITI.CITIZENSHIP.CZ_RIGHTS_RESP', 'Calls a right a responsibility, or the reverse.', '{"question":"Which is a responsibility of a Kenyan citizen?","wrong_answer":"To vote when 18","correct_answer":"To pay taxes"}'::jsonb, 'The child thinks anything good a citizen does is a responsibility.', 'Offer "To vote when 18" next to the right answer and ask the question again in a new context.', 'Ask what the state gives and what the citizen gives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.CITIZENSHIP.CZ_RIGHTS_RESP.M_CZ_VOTE_AGE', 'SOCI.G6.POLITI.CITIZENSHIP.CZ_RIGHTS_RESP', 'Says a citizen can vote at 14 or 16.', '{"question":"At what age can a Kenyan citizen vote?","wrong_answer":"16","correct_answer":"18"}'::jsonb, 'The child does not know the age.', 'Offer "16" next to the right answer and ask the question again in a new context.', 'Link voting with the identity card at 18.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.CITIZENSHIP.CZ_QUALITIES.M_CZ_PATRIOT', 'SOCI.G6.POLITI.CITIZENSHIP.CZ_QUALITIES', 'Says patriotism is only singing the anthem or waving the flag.', '{"question":"What is patriotism?","wrong_answer":"Only singing the anthem","correct_answer":"Love and loyalty for the country shown in actions"}'::jsonb, 'The child sees only the ceremony.', 'Offer "Only singing the anthem" next to the right answer and ask the question again in a new context.', 'Ask for an action that helps the country.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.CITIZENSHIP.CZ_QUALITIES.M_CZ_CORRUPT', 'SOCI.G6.POLITI.CITIZENSHIP.CZ_QUALITIES', 'Thinks giving a bribe to get service quickly is good citizenship.', '{"question":"Which action shows a good citizen?","wrong_answer":"Paying a bribe for quick service","correct_answer":"Refusing to bribe and reporting it"}'::jsonb, 'The child wants the service fast.', 'Offer "Paying a bribe for quick service" next to the right answer and ask the question again in a new context.', 'Ask whether honesty or speed matters most.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.CITIZENSHIP.CZ_RIGHTS_RESP.M_CZ_TAX_RIGHT', 'SOCI.G6.POLITI.CITIZENSHIP.CZ_RIGHTS_RESP', 'Calls paying taxes a right.', '{"question":"Is paying taxes a right or a responsibility?","wrong_answer":"A right","correct_answer":"A responsibility"}'::jsonb, 'The child sees taxes as something citizens do and calls everything a right.', 'Offer "A right" next to the right answer and ask the question again in a new context.', 'Sort: "I may" (right) and "I must" (responsibility).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.CITIZENSHIP.CZ_RIGHTS_RESP.M_CZ_ID_AGE', 'SOCI.G6.POLITI.CITIZENSHIP.CZ_RIGHTS_RESP', 'Thinks a citizen gets an ID card at 16.', '{"question":"At what age does a Kenyan citizen get a national ID card?","wrong_answer":"16","correct_answer":"18"}'::jsonb, 'Different ages are taught for different things.', 'Offer "16" next to the right answer and ask the question again in a new context.', 'Write 18: vote, ID card.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.CITIZENSHIP.CZ_QUALITIES.M_CZ_TOLERANCE', 'SOCI.G6.POLITI.CITIZENSHIP.CZ_QUALITIES', 'Thinks tolerance means agreeing with everyone.', '{"question":"What does tolerance mean?","wrong_answer":"Agreeing with everyone","correct_answer":"Accepting and respecting people who are different from you"}'::jsonb, 'Tolerance is mixed with agreement.', 'Offer "Agreeing with everyone" next to the right answer and ask the question again in a new context.', 'Act two learners who disagree politely.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.CITIZENSHIP.CZ_QUALITIES.M_CZ_PATRIOT_ONLY_SOLDIERS', 'SOCI.G6.POLITI.CITIZENSHIP.CZ_QUALITIES', 'Thinks only soldiers can be patriotic.', '{"question":"Can a farmer show patriotism?","wrong_answer":"No, only soldiers","correct_answer":"Yes, by working hard, paying taxes and caring for Kenya"}'::jsonb, 'Patriotism is linked to defending the country.', 'Offer "No, only soldiers" next to the right answer and ask the question again in a new context.', 'List ways different people show love for Kenya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.HUMAN_RIGHTS.HR_CATEGORIES.M_HR_CAT_SWAP', 'SOCI.G6.POLITI.HUMAN_RIGHTS.HR_CATEGORIES', 'Puts the right to vote among the economic rights.', '{"question":"Which category is the right to vote in?","wrong_answer":"Economic","correct_answer":"Political"}'::jsonb, 'The child links money and voting.', 'Offer "Economic" next to the right answer and ask the question again in a new context.', 'Ask: is it about running the country or earning a living?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.HUMAN_RIGHTS.HR_CATEGORIES.M_HR_EDU', 'SOCI.G6.POLITI.HUMAN_RIGHTS.HR_CATEGORIES', 'Puts the right to education among the political rights.', '{"question":"Which category is the right to education in?","wrong_answer":"Political","correct_answer":"Social"}'::jsonb, 'The child links school with the state.', 'Offer "Political" next to the right answer and ask the question again in a new context.', 'Ask whether it is about people''s welfare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.HUMAN_RIGHTS.HR_UPHOLD.M_HR_ONLY_POLICE', 'SOCI.G6.POLITI.HUMAN_RIGHTS.HR_UPHOLD', 'Says only the police uphold human rights.', '{"question":"Who helps to uphold human rights?","wrong_answer":"Only the police","correct_answer":"The courts, the Commission and every citizen"}'::jsonb, 'The child names one body.', 'Offer "Only the police" next to the right answer and ask the question again in a new context.', 'List five who help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.HUMAN_RIGHTS.HR_UPHOLD.M_HR_DAY', 'SOCI.G6.POLITI.HUMAN_RIGHTS.HR_UPHOLD', 'Gives 1 June (Madaraka Day) or another national holiday as Human Rights Day, mixing it up with the public holidays the child knows.', '{"question":"When is Human Rights Day?","wrong_answer":"1 June","correct_answer":"10 December"}'::jsonb, 'Human Rights Day is not a public holiday in Kenya, so the child reaches for a holiday date they already know.', 'Offer "1 June" next to the right answer and ask the question again in a new context.', 'List Kenya''s public holidays beside the international days, and mark 10 December as Human Rights Day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.HUMAN_RIGHTS.HR_CATEGORIES.M_HR_WORK_SOCIAL', 'SOCI.G6.POLITI.HUMAN_RIGHTS.HR_CATEGORIES', 'Puts the right to work and fair pay among social rights.', '{"question":"Under which category is the right to work and earn fair pay?","wrong_answer":"Social","correct_answer":"Economic"}'::jsonb, 'Work affects family life, so the child calls it social.', 'Offer "Social" next to the right answer and ask the question again in a new context.', 'Ask: is it about money and making a living?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.HUMAN_RIGHTS.HR_CATEGORIES.M_HR_PROPERTY_POLITICAL', 'SOCI.G6.POLITI.HUMAN_RIGHTS.HR_CATEGORIES', 'Puts the right to own property among political rights.', '{"question":"Under which category is the right to own property?","wrong_answer":"Political","correct_answer":"Economic"}'::jsonb, 'Property laws come from Parliament, so the child calls it political.', 'Offer "Political" next to the right answer and ask the question again in a new context.', 'Ask: is it about voting and leaders, or about wealth?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.HUMAN_RIGHTS.HR_UPHOLD.M_HR_KNCHR', 'SOCI.G6.POLITI.HUMAN_RIGHTS.HR_UPHOLD', 'Does not know the Kenya National Commission on Human Rights protects rights.', '{"question":"Which body in Kenya watches over human rights?","wrong_answer":"The Kenya Revenue Authority","correct_answer":"The Kenya National Commission on Human Rights"}'::jsonb, 'The child knows other national bodies by name.', 'Offer "The Kenya Revenue Authority" next to the right answer and ask the question again in a new context.', 'Match bodies to their jobs on cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.POLITI.HUMAN_RIGHTS.HR_UPHOLD.M_HR_SELF_NONE', 'SOCI.G6.POLITI.HUMAN_RIGHTS.HR_UPHOLD', 'Thinks individuals cannot uphold human rights.', '{"question":"How can a learner uphold human rights?","wrong_answer":"They cannot","correct_answer":"By respecting others, not bullying and reporting abuse"}'::jsonb, 'The child sees rights as the job of bodies and courts.', 'Offer "They cannot" next to the right answer and ask the question again in a new context.', 'List three things learners do daily that respect rights.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_CAUSES.M_PC_NO_CAUSE', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_CAUSES', 'Says conflicts have no cause and just happen.', '{"question":"Which is a cause of conflict?","wrong_answer":"None, conflicts just happen","correct_answer":"Competition for land and water"}'::jsonb, 'The child does not look for the reason.', 'Offer "None, conflicts just happen" next to the right answer and ask the question again in a new context.', 'Ask what two herders argue about at a dry well.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_CAUSES.M_PC_VIOLENCE_SOLVE', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_CAUSES', 'Says violence is the way to settle a quarrel.', '{"question":"How should a quarrel be settled?","wrong_answer":"By fighting","correct_answer":"By talking and listening"}'::jsonb, 'The child copies what he or she sees.', 'Offer "By fighting" next to the right answer and ask the question again in a new context.', 'Ask who wins after a fight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_METHODS.M_PC_MED_ARB', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_METHODS', 'Swaps mediation and arbitration.', '{"question":"In which method does a third person decide the answer?","wrong_answer":"Mediation","correct_answer":"Arbitration"}'::jsonb, 'The child mixes the two.', 'Offer "Mediation" next to the right answer and ask the question again in a new context.', 'Say a mediator helps and an arbitrator decides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_METHODS.M_PC_COURT_ONLY', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_METHODS', 'Says the only way to settle a dispute is in court.', '{"question":"Which is a peaceful way besides court?","wrong_answer":"None","correct_answer":"A council of elders"}'::jsonb, 'The child knows only courts.', 'Offer "None" next to the right answer and ask the question again in a new context.', 'Name Njuri Ncheke or Kaya elders.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_PROMOTE.M_PC_REVENGE', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_PROMOTE', 'Thinks taking revenge promotes peace.', '{"question":"Which action promotes peace?","wrong_answer":"Taking revenge","correct_answer":"Forgiving and talking"}'::jsonb, 'The child wants justice by force.', 'Offer "Taking revenge" next to the right answer and ask the question again in a new context.', 'Ask what revenge brings next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_PROMOTE.M_PC_RUMOUR', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_PROMOTE', 'Thinks spreading rumours is harmless.', '{"question":"What does spreading rumours do?","wrong_answer":"Nothing","correct_answer":"Starts or increases conflict"}'::jsonb, 'The child thinks words cannot hurt.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Tell a short story of a rumour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_CAUSES.M_PC_ONE_SIDE', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_CAUSES', 'Thinks conflicts are always caused by one bad side.', '{"question":"Two villages quarrel over a water point. What is the cause?","wrong_answer":"One village is bad","correct_answer":"Competition for scarce water"}'::jsonb, 'The child looks for someone to blame.', 'Offer "One village is bad" next to the right answer and ask the question again in a new context.', 'Ask what each village needs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_CAUSES.M_PC_HATE_SPEECH_OK', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_CAUSES', 'Thinks hate speech is only words and cannot cause conflict.', '{"question":"Can hate speech cause conflict?","wrong_answer":"No, it is only words","correct_answer":"Yes, it spreads anger between groups"}'::jsonb, 'The child thinks only actions cause harm.', 'Offer "No, it is only words" next to the right answer and ask the question again in a new context.', 'Discuss how angry words spread and lead to fights.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_METHODS.M_PC_NEG_DIALOGUE', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_METHODS', 'Thinks negotiation and dialogue are exactly the same.', '{"question":"Two traders bargain over a price until they agree. Is this dialogue or negotiation?","wrong_answer":"Dialogue, they are the same","correct_answer":"Negotiation"}'::jsonb, 'Both involve talking.', 'Offer "Dialogue, they are the same" next to the right answer and ask the question again in a new context.', 'Show that negotiation is bargaining to reach a deal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_METHODS.M_PC_MEDIATOR_DECIDES', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_METHODS', 'Thinks a mediator makes the final decision.', '{"question":"Does a mediator decide who is right?","wrong_answer":"Yes","correct_answer":"No, a mediator helps the two sides agree; an arbitrator decides"}'::jsonb, 'Both are third persons.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Act both: the mediator asks questions, the arbitrator gives a decision.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_PROMOTE.M_PC_SEPARATE', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_PROMOTE', 'Thinks keeping communities apart promotes peace.', '{"question":"Which promotes peace: keeping communities apart, or sports days between them?","wrong_answer":"Keeping them apart","correct_answer":"Sports and cultural days between them"}'::jsonb, 'Separation seems to stop fights.', 'Offer "Keeping them apart" next to the right answer and ask the question again in a new context.', 'Ask how people learn to trust each other if they never meet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_PROMOTE.M_PC_NYUMBA_KUMI', 'SOCI.G6.GOVERN.PEACE_AND_CONFLICT_RESOL.PC_PROMOTE', 'Does not know Nyumba Kumi helps keep peace.', '{"question":"What is Nyumba Kumi for?","wrong_answer":"Counting houses","correct_answer":"Neighbours working together for security and peace"}'::jsonb, 'The name means "ten houses" and the child takes it literally.', 'Offer "Counting houses" next to the right answer and ask the question again in a new context.', 'Explain the idea: groups of neighbours look out for each other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SOURCES.M_GR_LOAN_TAX', 'SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SOURCES', 'Calls a loan a tax.', '{"question":"Which is a tax?","wrong_answer":"A loan from a bank","correct_answer":"Income tax on salaries"}'::jsonb, 'The child thinks all money for government is tax.', 'Offer "A loan from a bank" next to the right answer and ask the question again in a new context.', 'Say a tax is compulsory and a loan must be repaid.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SOURCES.M_GR_COLLECTOR', 'SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SOURCES', 'Says the county assembly or the police collects national taxes.', '{"question":"Who collects national taxes in Kenya?","wrong_answer":"The police","correct_answer":"The Kenya Revenue Authority"}'::jsonb, 'The child does not know the body.', 'Offer "The police" next to the right answer and ask the question again in a new context.', 'Say KRA stands for Kenya Revenue Authority.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SPENDING.M_GR_LEVEL_SWAP', 'SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SPENDING', 'Says county governments pay teachers and national referral hospitals.', '{"question":"Which level of government pays teachers?","wrong_answer":"The county government","correct_answer":"The national government"}'::jsonb, 'The child mixes the two levels.', 'Offer "The county government" next to the right answer and ask the question again in a new context.', 'Say teachers are paid by the Teachers Service Commission.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SPENDING.M_GR_TAX_WASTE', 'SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SPENDING', 'Says taxes are kept by officials and not spent on services.', '{"question":"What is tax money used for?","wrong_answer":"Kept by officials","correct_answer":"Roads, schools, hospitals and security"}'::jsonb, 'The child hears complaints and thinks all is lost.', 'Offer "Kept by officials" next to the right answer and ask the question again in a new context.', 'List what is built with taxes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SOURCES.M_GR_VAT_INCOME', 'SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SOURCES', 'Mixes up income tax and value added tax.', '{"question":"A shopper pays a tax added to the price of soap. Which tax is this?","wrong_answer":"Income tax","correct_answer":"Value added tax (VAT)"}'::jsonb, 'Both are taxes the child hears about.', 'Offer "Income tax" next to the right answer and ask the question again in a new context.', 'Show a receipt with VAT printed on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SOURCES.M_GR_PRINT_MONEY', 'SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SOURCES', 'Thinks the government gets its money by printing more.', '{"question":"Where does most of the government''s money come from?","wrong_answer":"Printing more money","correct_answer":"Taxes"}'::jsonb, 'The child knows the government makes money (notes).', 'Offer "Printing more money" next to the right answer and ask the question again in a new context.', 'Explain that printing too much makes prices rise; taxes are the main source.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SPENDING.M_GR_COUNTY_DEFENCE', 'SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SPENDING', 'Thinks county governments pay for the army.', '{"question":"Which government pays for defence?","wrong_answer":"The county government","correct_answer":"The national government"}'::jsonb, 'The child does not sort functions by level.', 'Offer "The county government" next to the right answer and ask the question again in a new context.', 'Sort spending cards into national and county boxes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SPENDING.M_GR_DEBT_NONE', 'SOCI.G6.GOVERN.GOVERNMENT_REVENUE_AND_E.GR_SPENDING', 'Thinks the government does not spend on paying back loans.', '{"question":"Does the government spend some revenue on paying debts?","wrong_answer":"No","correct_answer":"Yes, it repays loans with interest"}'::jsonb, 'The child knows loans as revenue only.', 'Offer "No" next to the right answer and ask the question again in a new context.', 'Show that a loan must be paid back, like borrowing from a friend.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_KEYWORDS.M_PR_WHAT', 'SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_KEYWORDS', 'Says the preamble is the last part of the Constitution.', '{"question":"Where in the Constitution is the preamble?","wrong_answer":"At the end","correct_answer":"At the beginning"}'::jsonb, 'The child does not know the word.', 'Offer "At the end" next to the right answer and ask the question again in a new context.', 'Say pre means before.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_KEYWORDS.M_PR_SOVEREIGN_WHO', 'SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_KEYWORDS', 'Says the President holds the sovereign power.', '{"question":"In the preamble, who holds sovereign power?","wrong_answer":"The President","correct_answer":"The people of Kenya"}'::jsonb, 'The child links power with the President.', 'Offer "The President" next to the right answer and ask the question again in a new context.', 'Read the first words: We, the people of Kenya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_MEANING.M_PR_INDIVISIBLE', 'SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_MEANING', 'Says indivisible means divided into counties.', '{"question":"What does indivisible mean?","wrong_answer":"Divided into counties","correct_answer":"Cannot be divided"}'::jsonb, 'The child mixes it with devolution.', 'Offer "Divided into counties" next to the right answer and ask the question again in a new context.', 'Say in means not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_MEANING.M_PR_HERITAGE', 'SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_MEANING', 'Says heritage means money kept in the bank.', '{"question":"What is heritage?","wrong_answer":"Money kept in a bank","correct_answer":"What we receive from the past and pass on"}'::jsonb, 'The child links the word with inheritance of money.', 'Offer "Money kept in a bank" next to the right answer and ask the question again in a new context.', 'Ask about a rock painting or a forest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_KEYWORDS.M_PR_LAW_SECTIONS', 'SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_KEYWORDS', 'Thinks the preamble is a list of laws.', '{"question":"Is the preamble a list of laws?","wrong_answer":"Yes","correct_answer":"No, it is the opening statement of the values and aims of the people"}'::jsonb, 'The child thinks every part of the Constitution is a rule.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Read the preamble: it starts "We, the people of Kenya".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_KEYWORDS.M_PR_WE_GOVERNMENT', 'SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_KEYWORDS', 'Thinks "We, the people" means the government.', '{"question":"Who are \"We, the people of Kenya\" in the preamble?","wrong_answer":"The government","correct_answer":"All the people of Kenya"}'::jsonb, 'The child links the Constitution with the government.', 'Offer "The government" next to the right answer and ask the question again in a new context.', 'Ask who voted for the Constitution in the 2010 referendum.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_MEANING.M_PR_DIVERSITY_DIVISION', 'SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_MEANING', 'Thinks diversity means division.', '{"question":"What does diversity mean in the preamble?","wrong_answer":"Division and quarrels","correct_answer":"Our many differences, such as cultures and languages, which we respect"}'::jsonb, 'Diversity and division sound alike.', 'Offer "Division and quarrels" next to the right answer and ask the question again in a new context.', 'List the different communities in the class: that is diversity.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_MEANING.M_PR_RULE_LAW', 'SOCI.G6.GOVERN.THE_PREAMBLE_OF_THE_CONS.PR_MEANING', 'Thinks the rule of law means leaders are above the law.', '{"question":"What does the rule of law mean?","wrong_answer":"Leaders can do as they like","correct_answer":"Everyone, including leaders, must obey the law"}'::jsonb, 'The child links rule with rulers.', 'Offer "Leaders can do as they like" next to the right answer and ask the question again in a new context.', 'Ask whether a leader may break a traffic law.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
